# --------------------------------------------------------------------------
# UNIFIED CONFIG FILE
# One physical file (nomo.json) holds market config, hatcher config, and both
# runtimes as sections. The four *_FILE constants above become LOGICAL keys:
# save_json/load_json redirect them to sections of nomo.json, so every existing
# call site and all migration logic keep working unchanged. On first run the
# old separate files are auto-imported and backed up.
# --------------------------------------------------------------------------
NOMO_FILE = BASE_DIR / "nomo.json"
NOMO_LAST_GOOD_FILE = BASE_DIR / "nomo.json.last_good"

# Map each logical file constant -> its section key inside nomo.json.
_MERGED_SECTIONS = {
    str(CONFIG_FILE): "market",
    str(HATCHER_CONFIG_FILE): "hatcher",
    str(RUNTIME_FILE): "runtime_market",
    str(HATCHER_RUNTIME_FILE): "runtime_hatcher",
    str(BOOSTER_CONFIG_FILE): "booster",
    str(BOOSTER_RUNTIME_FILE): "runtime_booster",
}

# V4.81.14: unified nomo.json write guard.
#
# Runtime/config sections share one physical JSON file, and many call sites save
# defensively even when nothing changed.  Keep real state durable (changed data
# is still written immediately), but avoid rewriting the same unified snapshot.
# A single RLock also prevents two threads from interleaving read/modify/write.
_NOMO_CACHE = {
    "data": None,
    "persisted_signature": None,
    "writes": 0,
    "skips": 0,
    "recovered_from_last_good": False,
    "recovery_blocked": False,
    "last_read_error": "",
}
_NOMO_FILE_LOCK = threading.RLock()


def _nomo_signature(data):
    """Stable semantic signature used only to suppress identical disk writes."""
    try:
        return json.dumps(data, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    except Exception:
        # Keep the save path robust for any odd legacy value.  Falling back to
        # repr may miss an optimization, but must never block a real save.
        return repr(data)


def _nomo_parse_dict_file(path):
    path = Path(path)
    try:
        if not path.exists():
            return None, "missing"
        data = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(data, dict):
            return None, "root is not an object"
        return data, ""
    except Exception as exc:
        return None, str(exc)


def _nomo_atomic_text(path, text):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    try:
        tmp.write_text(text, encoding="utf-8")
        os.replace(str(tmp), str(path))
    except Exception:
        path.write_text(text, encoding="utf-8")
        try:
            if tmp.exists():
                tmp.unlink()
        except Exception:
            pass


def _nomo_quarantine_corrupt_file(path):
    path = Path(path)
    if not path.exists():
        return ""
    stamp = time.strftime("%Y%m%d-%H%M%S")
    target = path.with_name(path.name + f".corrupt-{stamp}")
    suffix = 1
    while target.exists():
        target = path.with_name(path.name + f".corrupt-{stamp}-{suffix}")
        suffix += 1
    try:
        os.replace(str(path), str(target))
        return str(target)
    except Exception:
        return ""


def _nomo_seed_last_good(data):
    """Best-effort seed/update of the recoverable unified snapshot."""
    try:
        pretty = json.dumps(data, indent=2, ensure_ascii=False)
        _nomo_atomic_text(NOMO_LAST_GOOD_FILE, pretty)
        return True
    except Exception:
        return False


def _nomo_read_all():
    """Read the whole unified file with last-good corruption recovery."""
    with _NOMO_FILE_LOCK:
        if _NOMO_CACHE["data"] is None:
            data, primary_err = _nomo_parse_dict_file(NOMO_FILE)
            primary_exists = NOMO_FILE.exists()

            if data is not None:
                _NOMO_CACHE["data"] = data
                _NOMO_CACHE["recovery_blocked"] = False
                _NOMO_CACHE["last_read_error"] = ""
                # Seed protection immediately after updating from an older build.
                if not NOMO_LAST_GOOD_FILE.exists():
                    _nomo_seed_last_good(data)
            elif primary_exists:
                recovered, backup_err = _nomo_parse_dict_file(NOMO_LAST_GOOD_FILE)
                if recovered is not None:
                    quarantined = _nomo_quarantine_corrupt_file(NOMO_FILE)
                    _NOMO_CACHE["data"] = recovered
                    _NOMO_CACHE["recovered_from_last_good"] = True
                    _NOMO_CACHE["recovery_blocked"] = False
                    _NOMO_CACHE["last_read_error"] = str(primary_err or "invalid nomo.json")
                    # Restore the primary file before any section save can occur.
                    _nomo_atomic_text(
                        NOMO_FILE,
                        json.dumps(recovered, indent=2, ensure_ascii=False),
                    )
                    print(
                        "[NOMO] recovered corrupt nomo.json from last-good"
                        + (f"; quarantined={quarantined}" if quarantined else "")
                    )
                else:
                    # Never turn a malformed unified config into an empty one and
                    # overwrite it on the next innocent runtime save. Fail closed.
                    _NOMO_CACHE["data"] = {}
                    _NOMO_CACHE["recovery_blocked"] = True
                    _NOMO_CACHE["last_read_error"] = (
                        f"nomo.json invalid: {primary_err}; last-good invalid: {backup_err}"
                    )
                    print("[NOMO] ERROR: unified config recovery blocked; refusing nomo.json writes")
            else:
                # Brand-new install: no primary file is not corruption.
                recovered, _backup_err = _nomo_parse_dict_file(NOMO_LAST_GOOD_FILE)
                if recovered is not None:
                    _NOMO_CACHE["data"] = recovered
                    _NOMO_CACHE["recovered_from_last_good"] = True
                    _NOMO_CACHE["recovery_blocked"] = False
                    _nomo_atomic_text(
                        NOMO_FILE,
                        json.dumps(recovered, indent=2, ensure_ascii=False),
                    )
                else:
                    _NOMO_CACHE["data"] = {}
                    _NOMO_CACHE["recovery_blocked"] = False
                    _NOMO_CACHE["last_read_error"] = ""

            _NOMO_CACHE["persisted_signature"] = _nomo_signature(_NOMO_CACHE["data"])
        return _NOMO_CACHE["data"]


def _nomo_write_all(data, force=False):
    """Atomically persist nomo.json and its recoverable last-good snapshot.

    Changed state is never delayed/debounced. If both the primary and backup were
    unreadable on startup, writes fail closed so an innocent runtime save cannot
    destroy the user's other unified sections.
    """
    with _NOMO_FILE_LOCK:
        if _NOMO_CACHE.get("recovery_blocked"):
            return False

        signature = _nomo_signature(data)
        if not force and _NOMO_CACHE.get("persisted_signature") == signature:
            _NOMO_CACHE["data"] = data
            _NOMO_CACHE["skips"] = int(_NOMO_CACHE.get("skips", 0) or 0) + 1
            return False

        pretty = json.dumps(data, indent=2, ensure_ascii=False)
        BASE_DIR.mkdir(parents=True, exist_ok=True)
        _nomo_atomic_text(NOMO_FILE, pretty)
        # The exact successfully serialized unified state is the last-good copy.
        _nomo_atomic_text(NOMO_LAST_GOOD_FILE, pretty)

        _NOMO_CACHE["data"] = data
        _NOMO_CACHE["persisted_signature"] = signature
        _NOMO_CACHE["writes"] = int(_NOMO_CACHE.get("writes", 0) or 0) + 1
        return True


def _migrate_legacy_files():
    """First-run: import the 4 old separate files into nomo.json, back them up."""
    if NOMO_FILE.exists():
        return  # already migrated
    merged = {}
    imported_any = False
    for legacy_path, section in _MERGED_SECTIONS.items():
        p = Path(legacy_path)
        if p.exists():
            try:
                merged[section] = json.loads(p.read_text())
                imported_any = True
            except Exception:
                merged[section] = {}
    if imported_any:
        _nomo_write_all(merged)
        # Back up (rename) the old files so we don't read them again but keep them.
        for legacy_path in _MERGED_SECTIONS:
            p = Path(legacy_path)
            if p.exists():
                try:
                    bak = p.with_suffix(p.suffix + ".bak")
                    os.replace(str(p), str(bak))
                except Exception:
                    pass

COOKIE_CACHE = BASE_DIR / "cookie_cache.json"

STATE_FOLDER_NAME = "nomo_rejoiner"
LEGACY_STATE_FOLDER_NAME = "gag_rejoiner"
LEGACY_DELTA_STATE_MIGRATION_VERSION = 456


def _legacy_state_payload_timestamp(path):
    """Prefer payload ts; fall back to mtime for non-state/invalid files."""
    path = Path(path)
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
        ts = int(payload.get("ts", 0) or 0)
        if ts > 0:
            return ts
    except Exception:
        pass
    try:
        return int(path.stat().st_mtime)
    except Exception:
        return 0


def _replace_legacy_state_folder_strings(value):
    """Recursively patch exact /gag_rejoiner/ path components."""
    changed = False

    if isinstance(value, dict):
        for key in list(value.keys()):
            new_value, item_changed = _replace_legacy_state_folder_strings(
                value[key]
            )
            if item_changed:
                value[key] = new_value
                changed = True
        return value, changed

    if isinstance(value, list):
        for index, item in enumerate(list(value)):
            new_value, item_changed = _replace_legacy_state_folder_strings(item)
            if item_changed:
                value[index] = new_value
                changed = True
        return value, changed

    if isinstance(value, str):
        old_component = f"/{LEGACY_STATE_FOLDER_NAME}/"
        if old_component in value:
            return (
                value.replace(
                    old_component,
                    f"/{STATE_FOLDER_NAME}/",
                ),
                True,
            )

    return value, False


def _unique_legacy_quarantine_path(parent):
    stamp = time.strftime("%Y%m%d-%H%M%S")
    candidate = parent / (
        f"{LEGACY_STATE_FOLDER_NAME}_legacy_v456_{stamp}"
    )
    suffix = 1
    while candidate.exists():
        candidate = parent / (
            f"{LEGACY_STATE_FOLDER_NAME}_legacy_v456_{stamp}_{suffix}"
        )
        suffix += 1
    return candidate


def migrate_legacy_delta_state_folder_once(cfg=None, force=False):
    """Move/quarantine the obsolete Delta gag_rejoiner state folder safely.

    The canonical folder always wins unless the legacy file has a newer payload
    timestamp. The old directory is renamed after migration so state discovery
    can no longer select it, while preserving rollback data.
    """
    cfg = cfg if isinstance(cfg, dict) else {}
    marker = int(
        cfg.get("_nomo_legacy_delta_state_cleanup_migration", 0) or 0
    )
    if marker >= LEGACY_DELTA_STATE_MIGRATION_VERSION and not force:
        return {
            "ran": False,
            "moved": 0,
            "replaced": 0,
            "quarantined": "",
            "paths_patched": False,
        }

    workspace = DELTA_GLOBAL_WORKSPACE_DIR
    canonical = workspace / STATE_FOLDER_NAME
    legacy = workspace / LEGACY_STATE_FOLDER_NAME
    backup_root = BASE_DIR / "legacy_state_backups"
    moved = 0
    replaced = 0
    quarantined = ""
    paths_patched = False

    try:
        canonical.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass

    if legacy.exists() and legacy.is_dir():
        try:
            backup_root.mkdir(parents=True, exist_ok=True)
        except Exception:
            pass

        try:
            legacy_items = list(legacy.iterdir())
        except Exception:
            legacy_items = []

        for old_path in legacy_items:
            if not old_path.is_file():
                continue

            new_path = canonical / old_path.name
            try:
                if not new_path.exists():
                    shutil.copy2(old_path, new_path)
                    moved += 1
                    continue

                old_ts = _legacy_state_payload_timestamp(old_path)
                new_ts = _legacy_state_payload_timestamp(new_path)

                if old_ts > new_ts:
                    backup_name = (
                        f"{new_path.name}.pre_v456."
                        f"{int(time.time())}.bak"
                    )
                    backup_path = backup_root / backup_name
                    shutil.copy2(new_path, backup_path)
                    shutil.copy2(old_path, new_path)
                    replaced += 1
            except Exception:
                continue

        try:
            quarantine_path = _unique_legacy_quarantine_path(workspace)
            legacy.rename(quarantine_path)
            quarantined = str(quarantine_path)
        except Exception:
            quarantined = ""

    # Patch all sections in nomo.json in one pass.
    try:
        all_data = _nomo_read_all()
        _, paths_patched = _replace_legacy_state_folder_strings(all_data)
        if paths_patched:
            _nomo_write_all(all_data)
    except Exception:
        paths_patched = False

    # Also patch the optional template so it cannot recreate legacy paths.
    try:
        if CONFIG_TEMPLATE_FILE.exists():
            template = json.loads(
                CONFIG_TEMPLATE_FILE.read_text(encoding="utf-8")
            )
            _, template_changed = _replace_legacy_state_folder_strings(
                template
            )
            if template_changed:
                CONFIG_TEMPLATE_FILE.write_text(
                    json.dumps(template, indent=2),
                    encoding="utf-8",
                )
                paths_patched = True
    except Exception:
        pass

    cfg["_nomo_legacy_delta_state_cleanup_migration"] = (
        LEGACY_DELTA_STATE_MIGRATION_VERSION
    )
    cfg["_nomo_legacy_delta_state_cleanup_summary"] = {
        "moved": moved,
        "replaced": replaced,
        "quarantined": quarantined,
        "paths_patched": bool(paths_patched),
        "completed_at": int(time.time()),
    }

    return {
        "ran": True,
        "moved": moved,
        "replaced": replaced,
        "quarantined": quarantined,
        "paths_patched": bool(paths_patched),
    }


