# ============================================================
# JSONBIN HATCHER ROUTING
# ============================================================

def mask_secret(value):
    value = str(value or "")
    if not value:
        return ""
    if len(value) <= 8:
        return "***"
    return value[:4] + "***" + value[-4:]


def jsonbin_headers(cfg, write=False):
    key = str(cfg.get("jsonbin_api_key", "")).strip()
    header_name = str(cfg.get("jsonbin_key_header", "X-Master-Key") or "X-Master-Key").strip()

    headers = {
        "Content-Type": "application/json",
        "User-Agent": "nomo-rejoin/jsonbin"
    }

    if key:
        headers[header_name] = key

    if not write:
        headers["X-Bin-Meta"] = "false"

    return headers


def jsonbin_record_from_response(data):
    if isinstance(data, dict) and "record" in data and isinstance(data.get("record"), dict):
        return data["record"]
    if isinstance(data, dict):
        return data
    return {}


def jsonbin_read_bin(cfg):
    bin_id = str(cfg.get("jsonbin_bin_id", "")).strip()

    if is_placeholder_value(bin_id):
        return None, "missing bin id"

    timeout = int(cfg.get("jsonbin_timeout_seconds", 8))
    headers = jsonbin_headers(cfg, write=False)

    urls = [
        f"https://api.jsonbin.io/v3/b/{bin_id}/latest",
        f"https://api.jsonbin.io/v3/b/{bin_id}",
    ]

    last_err = ""

    for url in urls:
        try:
            req = urllib.request.Request(url, method="GET", headers=headers)
            with urllib.request.urlopen(req, timeout=timeout) as r:
                text = r.read().decode("utf-8", "replace")
            data = json.loads(text)
            return jsonbin_record_from_response(data), None

        except urllib.error.HTTPError as e:
            try:
                body = e.read().decode("utf-8", "replace")
            except Exception:
                body = str(e)
            last_err = f"http {e.code}: {cut(body, 80)}"

        except Exception as e:
            last_err = str(e)

    return None, last_err or "jsonbin read failed"


def get_jsonbin_cache(rt):
    if "_jsonbin_hatchers_cache" not in rt:
        rt["_jsonbin_hatchers_cache"] = {
            "ts": 0,
            "data": None,
            "err": "not loaded"
        }
    return rt["_jsonbin_hatchers_cache"]


def read_hatchers_cached(cfg, rt, force=False):
    cache = get_jsonbin_cache(rt)
    cache_age = now() - int(cache.get("ts", 0) or 0)
    cache_seconds = max(30, int(cfg.get("jsonbin_cache_seconds", 20) or 20))
    is_cloudflare = backend_provider(cfg) == "cloudflare"

    if not force and cache_age < cache_seconds:
        if cache.get("data") is not None:
            # A previous failed refresh may have left last_error behind. The last
            # good payload is still intentionally usable until normal stale checks.
            return cache.get("data"), None
        if is_cloudflare and cache.get("last_error"):
            # Cache the failure too; do not let multiple Market routes retry the
            # same unavailable Worker inside the normal cache window.
            return None, str(cache.get("last_error"))

    data, err = backend_read_hatchers(cfg)
    cache["ts"] = now()

    if is_cloudflare:
        if data is not None and not err:
            cache["data"] = data
            cache["err"] = None
            cache["last_error"] = ""
            cache["last_good_ts"] = now()
            save_runtime(rt)
            return data, None

        # Never destroy a previously good Cloudflare pool just because one fetch
        # failed. Keep it and let pick_jsonbin_hatcher() apply its existing
        # per-record stale_seconds check.
        cache["last_error"] = str(err or "Cloudflare read failed")
        cache["err"] = None if cache.get("data") is not None else cache["last_error"]
        save_runtime(rt)
        if cache.get("data") is not None:
            return cache.get("data"), None
        return None, cache["last_error"]

    # Preserve the old JSONBin behavior exactly.
    cache["data"] = data
    cache["err"] = err
    save_runtime(rt)
    return data, err


def shared_backend_label(cfg):
    provider = str(cfg.get("backend_provider", "jsonbin") or "jsonbin").strip().lower()
    return "cloudflare" if provider == "cloudflare" else "jsonbin"


def pick_jsonbin_hatcher(cfg, rt, force=False):
    if not cfg.get("jsonbin_hatchers_enabled", False):
        return None, None, f"{shared_backend_label(cfg)} off"

    data, err = read_hatchers_cached(cfg, rt, force=force)

    if err or not data:
        return None, None, f"{shared_backend_label(cfg)} {err}"

    hatchers = data.get("hatchers", data if isinstance(data, dict) else {})

    if not isinstance(hatchers, dict):
        return None, None, f"{shared_backend_label(cfg)} bad format"

    stale_seconds = max(60, int(cfg.get("jsonbin_stale_seconds", 7200) or 7200))
    min_pets = int(cfg.get("jsonbin_min_hatcher_pets", 200))
    choices = []
    skipped_stale = 0
    skipped_future = 0
    skipped_no_time = 0

    for name, h in hatchers.items():
        if not isinstance(h, dict):
            continue

        if not h.get("enabled", True):
            continue

        pool_mode = str(h.get("mode") or h.get("role") or "hatcher").strip().lower()
        if pool_mode not in ("", "hatcher"):
            continue

        status = str(h.get("status", "ready")).lower()
        if status not in ["ready", "idle", "available", "ok", "online", "ingame"]:
            continue

        link = str(h.get("server_link", "") or h.get("restock_link", "")).strip()
        if not link or link.startswith("PUT_"):
            continue

        try:
            pets = int(h.get("pet_count", 0))
        except Exception:
            pets = 0

        ready_by_egg = bool(h.get("ready_by_egg", False))
        if pets < min_pets and not ready_by_egg:
            continue

        updated_at = _cloudflare_item_updated_seconds(h)
        if not updated_at:
            skipped_no_time += 1
            continue

        age = now() - updated_at if updated_at else 999999
        if age < -60:
            skipped_future += 1
            continue
        age = max(0, age)
        if age > stale_seconds:
            skipped_stale += 1
            continue

        choices.append({
            "name": str(name),
            "link": link,
            "pets": pets,
            "age": age,
            "updated_at": updated_at,
        })

    if not choices:
        details = []
        if skipped_stale:
            details.append(f"stale={skipped_stale}")
        if skipped_no_time:
            details.append(f"no_time={skipped_no_time}")
        if skipped_future:
            details.append(f"future_time={skipped_future}")
        suffix = " (" + ", ".join(details) + ")" if details else ""
        return None, None, "no ready hatcher" + suffix

    choices.sort(key=lambda x: (x["pets"], x["updated_at"]), reverse=True)
    best = choices[0]
    return best["link"], best, None



def market_booster_pool_entries(cfg, rt=None, force=False):
    """Return usable Booster backend records, never ordinary Hatchers."""
    if not cfg.get("market_booster_pool_enabled", True):
        return [], "Booster pool disabled"
    if not cfg.get("jsonbin_hatchers_enabled", False):
        return [], "shared backend disabled"

    rt = load_runtime() if rt is None else rt
    data, err = read_hatchers_cached(cfg, rt, force=force)
    if err or not isinstance(data, dict):
        return [], str(err or "bad backend response")

    raw = data.get("hatchers", {})
    if not isinstance(raw, dict):
        return [], "bad backend pool format"

    stale_seconds = max(
        60,
        int(cfg.get("market_booster_stale_seconds", 7200) or 7200),
    )
    require_matches = bool(
        cfg.get("market_booster_require_matches", True)
    )
    choices = []

    for key, item in raw.items():
        if not isinstance(item, dict):
            continue

        mode = str(
            item.get("mode") or item.get("role") or ""
        ).strip().lower()
        if mode != "booster":
            continue
        if not item.get("enabled", True):
            continue

        status = str(item.get("status") or "").strip().lower()
        if status not in {
            "available", "online", "ingame", "ready", "ok",
        }:
            continue

        raw_link = str(
            item.get("server_link") or ""
        ).strip()
        (
            link,
            private_place_id,
            private_link_code,
            private_access_code,
        ) = normalized_private_route_link(
            raw_link,
            record=item,
            default_place_id=str(
                cfg.get(
                    "market_booster_expected_place_id",
                    "126884695634066",
                )
                or "126884695634066"
            ),
        )

        # A placeId-only link is a public-server route.
        if not link or not (
            private_link_code
            or private_access_code
        ):
            continue

        expected_job_id = str(
            item.get("job_id")
            or item.get("booster_job_id")
            or ""
        ).strip()

        if not expected_job_id:
            continue

        updated_at = _cloudflare_item_updated_seconds(item)
        if not updated_at:
            try:
                updated_at = int(item.get("updated_at", 0) or 0)
            except Exception:
                updated_at = 0
        age = now() - updated_at if updated_at else 999999
        if age > stale_seconds:
            continue

        probe_status = str(
            item.get("booster_probe_status") or ""
        ).strip().lower()
        if probe_status and probe_status != "ready":
            continue
        if item.get("booster_probe_reportable") is False:
            continue

        matches = item.get("boosting_matches", [])
        if not isinstance(matches, list):
            matches = []
        matches = [m for m in matches if isinstance(m, dict)]

        try:
            match_count = int(
                item.get("boosting_match_count", len(matches))
                or len(matches)
            )
        except Exception:
            match_count = len(matches)
        match_count = max(match_count, len(matches))
        if require_matches and match_count <= 0:
            continue

        try:
            pet_count = int(item.get("pet_count", 0) or 0)
        except Exception:
            pet_count = 0

        name = str(
            item.get("booster_name")
            or item.get("name")
            or item.get("hatcher_name")
            or key
        ).strip() or str(key)

        choices.append({
            "name": name,
            "link": link,
            "private_place_id": private_place_id,
            "private_link_code": private_link_code,
            "private_access_code": private_access_code,
            "route_kind": (
                "privateServerLinkCode"
                if private_link_code
                else "accessCode"
            ),
            "expected_job_id": expected_job_id,
            "age": max(0, age),
            "updated_at": updated_at,
            "pet_count": pet_count,
            "match_count": match_count,
            "matches": matches,
            "status": status,
            "probe_status": probe_status or "ready",
            "raw": dict(item),
        })

    choices.sort(
        key=lambda item: (
            -int(item.get("match_count", 0) or 0),
            int(item.get("age", 999999) or 999999),
            str(item.get("name") or "").lower(),
        )
    )
    return choices, None


def market_booster_pet_label(item):
    if not isinstance(item, dict):
        return "?"
    name = str(item.get("name") or "?")
    age = item.get("age")
    weight = item.get("base_weight_age1_kg")
    if weight is None:
        weight = item.get("base_weight_kg")
    mutation = str(item.get("mutation") or "Normal")

    parts = [name]
    if isinstance(age, (int, float)):
        parts.append(f"a{int(age)}")
    if isinstance(weight, (int, float)):
        parts.append(f"{float(weight):.2f}kg")
    if mutation and mutation.lower() not in {"normal", "none"}:
        parts.append(mutation)
    return " ".join(parts)


def market_booster_top_summary(entry, cfg):
    limit = max(
        1,
        int(cfg.get("market_booster_top_pets", 3) or 3),
    )
    matches = entry.get("matches", []) if isinstance(entry, dict) else []
    labels = [
        market_booster_pet_label(item)
        for item in matches[:limit]
    ]
    return cut(", ".join(labels) or "-", 44)


def market_booster_hold_info(rt_tab):
    if str(rt_tab.get("target") or "") != "booster":
        return False, False, 0
    if not rt_tab.get("manual_booster_hold_active", False):
        return False, True, 0

    until = int(rt_tab.get("manual_booster_hold_until", 0) or 0)
    if until <= 0:
        return True, False, 0
    left = until - now()
    if left > 0:
        return True, False, left
    return False, True, 0


def market_prepare_booster_route(rt_tab, booster, cfg):
    hold_seconds = max(
        0,
        int(cfg.get("market_booster_manual_hold_seconds", 0) or 0),
    )
    rt_tab["booster_route_link"] = str(booster.get("link") or "")
    rt_tab["booster_route_name"] = str(booster.get("name") or "booster")
    rt_tab["booster_route_record_ts"] = int(
        booster.get("updated_at", 0) or 0
    )
    rt_tab["booster_route_job_id"] = str(
        booster.get("expected_job_id")
        or booster.get("job_id")
        or ""
    )
    rt_tab["manual_booster_hold_active"] = True
    rt_tab["manual_booster_hold_until"] = (
        now() + hold_seconds if hold_seconds > 0 else 0
    )
    rt_tab["target"] = "booster"


def market_clear_booster_route(rt_tab):
    rt_tab["manual_booster_hold_active"] = False
    rt_tab["manual_booster_hold_until"] = 0
    rt_tab["booster_route_link"] = ""
    rt_tab["booster_route_name"] = ""
    rt_tab["booster_route_record_ts"] = 0
    rt_tab["booster_route_job_id"] = ""




def market_run_booster_hard_join_queue(
    cfg,
    tab,
    reason,
    expected_place_id="",
    expected_job_id="",
):
    """Direct exact-PID hard open for one manual Market -> Booster route."""
    package = str(tab.get("package") or "")
    if not package:
        return False, "package missing"

    rt = load_runtime()
    rt_tab = get_runtime_tab(rt, package)

    # A manual menu action must not sit silently behind a stale queue lock.
    holder = str(rt.get("_open_lock_pkg", "") or "")
    held_at = int(rt.get("_open_lock_at", 0) or 0)
    max_hold = max(
        30,
        int(
            cfg.get(
                "single_flight_max_seconds",
                420,
            )
            or 420
        ),
    )

    if holder:
        stale = (
            held_at <= 0
            or now() - held_at >= max_hold
        )
        if holder == package or stale:
            rt["_open_lock_pkg"] = ""
            rt["_open_lock_at"] = 0
            save_runtime(rt)
        else:
            return (
                False,
                f"another package is opening: {short_pkg(holder)}",
            )

    clear()
    banner("MANUAL BOOSTER HARD JOIN", cfg)
    print(f"Package : {package}")
    print(f"Target  : Booster")
    print(
        "Job     : "
        + str(expected_job_id or "-")[:24]
    )
    print("")
    print(
        col(
            "1/3 Stopping only the selected package PID...",
            YELLOW,
        )
    )
    log_activity(
        "manual Booster direct hard join started",
        package,
        CYAN,
    )

    # This direct user-triggered navigation intentionally bypasses the
    # pre-open provider gate. The post-open wait still detects a real
    # package-scoped challenge and can start the configured solver.
    rt_tab["solver_preflight_generation"] = ""
    rt_tab["solver_preflight_reason"] = ""
    rt_tab["note"] = "manual Booster direct hard join"
    save_runtime(rt)

    ok, open_note = open_target(
        tab,
        rt_tab,
        cfg,
        "booster",
        reason,
        force=True,
        rt=rt,
        mode="hard_force",
    )
    save_runtime(rt)

    if not ok:
        print(
            col(
                "FAILED: " + str(open_note),
                RED,
            )
        )
        return False, str(open_note)

    opened_at = int(
        rt_tab.get("last_open", now())
        or now()
    )

    print(
        col(
            "2/3 Private link opened.",
            GREEN,
        )
    )
    print(
        col(
            "3/3 Waiting for exact Booster server...",
            CYAN,
        )
    )
    print("")

    timeout = max(
        30,
        int(
            cfg.get(
                "market_booster_manual_route_wait_seconds",
                90,
            )
            or 90
        ),
    )

    fresh_ok, fresh_note = wait_until_fresh_after_open(
        tab,
        cfg,
        rt,
        opened_at,
        timeout_override=timeout,
        # No blind pre-open solver. A real challenge detected after launch
        # may still start the configured provider once.
        allow_solver_probe=True,
        expected_place_id=str(
            expected_place_id or ""
        ),
        expected_job_id=str(
            expected_job_id or ""
        ),
    )

    save_runtime(rt)

    if not fresh_ok:
        return (
            False,
            "Booster hard join failed: "
            + str(fresh_note),
        )

    return True, "exact Booster server confirmed"



def market_run_route_queue(cfg, tabs, target, reason):
    """Use the normal route queue: task reuse first, one exact-PID fallback."""
    rt = load_runtime()
    open_queue, core = make_rejoin_core(cfg, rt)
    queued = []

    for tab in tabs:
        package = str(tab.get("package") or "")
        if not package:
            continue
        added, note = core.queue_route_retry(
            tab,
            target,
            reason,
            metadata={
                "manual_booster_route": target == "booster",
            },
        )
        if added:
            queued.append(package)
        else:
            log_activity(
                f"manual route queue skipped: {note}",
                package,
                YELLOW,
            )

    if not core.drain(delay_seconds=1):
        return False, "stopped"

    save_runtime(rt)
    if not queued:
        return False, "nothing queued"
    return True, f"routed {len(queued)} package(s)"


def market_manual_join_booster(cfg, booster, package):
    tab = next(
        (
            tab
            for tab in cfg.get("tabs", [])
            if str(tab.get("package") or "")
            == str(package or "")
        ),
        None,
    )
    if not isinstance(tab, dict):
        return False, "package not configured"

    raw_link = str(booster.get("link") or "").strip()
    if not raw_link:
        return False, "Booster has no link"

    (
        link,
        expected_place,
        private_link_code,
        private_access_code,
    ) = normalized_private_route_link(
        raw_link,
        record=booster.get("raw"),
        default_place_id=str(
            cfg.get(
                "market_booster_expected_place_id",
                "126884695634066",
            )
            or "126884695634066"
        ),
    )

    if not link or not (
        private_link_code
        or private_access_code
    ):
        return (
            False,
            "Booster backend link is public-only; "
            "private code is missing",
        )

    booster = dict(booster)
    booster["link"] = link
    expected_job_id = str(
        booster.get("expected_job_id")
        or (booster.get("raw") or {}).get("job_id")
        or (booster.get("raw") or {}).get("booster_job_id")
        or ""
    ).strip()

    if not expected_job_id:
        return (
            False,
            "Booster backend job_id missing; wait for its next report",
        )

    route_started_at = now()
    rt = load_runtime()
    rt_tab = get_runtime_tab(rt, package)
    market_prepare_booster_route(
        rt_tab,
        booster,
        cfg,
    )
    rt_tab["manual_booster_route_started_at"] = (
        route_started_at
    )
    save_runtime(rt)

    ok, note = market_run_booster_hard_join_queue(
        cfg,
        tab,
        (
            "manual Booster hard private join: "
            f"{booster.get('name', 'booster')}"
        ),
        expected_place_id=expected_place,
        expected_job_id=expected_job_id,
    )

    latest_rt = load_runtime()
    latest_tab = get_runtime_tab(
        latest_rt,
        package,
    )

    if not ok:
        market_clear_booster_route(latest_tab)
        latest_tab["target"] = "market"
        save_runtime(latest_rt)
        return False, note

    confirmed, state, state_err = (
        market_booster_route_state_confirmed(
            tab,
            cfg,
            route_started_at,
            expected_place,
            expected_job_id,
        )
    )
    actual_place = str(
        (state or {}).get("place_id")
        or ""
    )

    if not confirmed:
        market_clear_booster_route(latest_tab)
        latest_tab["target"] = "market"
        latest_tab["note"] = (
            "Booster route not confirmed"
        )
        save_runtime(latest_rt)

        detail = str(
            state_err
            or (
                f"wrong place {actual_place}"
                if actual_place
                else "no fresh Booster state"
            )
        )
        return (
            False,
            "Booster route not confirmed: "
            + cut(detail, 90),
        )

    active, _expired, left = market_booster_hold_info(
        latest_tab
    )
    hold_note = (
        "manual return"
        if active and left <= 0
        else (
            f"hold {format_age(left)}"
            if active
            else "hold ended"
        )
    )
    latest_tab["note"] = (
        f"joined {booster.get('name', 'booster')}; "
        f"{hold_note}"
    )
    save_runtime(latest_rt)
    return (
        True,
        f"joined {booster.get('name', 'booster')}; "
        f"{hold_note}",
    )


def market_return_packages_from_booster(cfg, packages):
    wanted = set(packages or [])
    tabs = [
        tab for tab in cfg.get("tabs", [])
        if str(tab.get("package") or "") in wanted
    ]
    if not tabs:
        return False, "no packages selected"

    rt = load_runtime()
    for tab in tabs:
        rt_tab = get_runtime_tab(rt, tab.get("package"))
        rt_tab["manual_booster_hold_active"] = False
        rt_tab["manual_booster_hold_until"] = 0
    save_runtime(rt)

    ok, note = market_run_route_queue(
        cfg,
        tabs,
        "market",
        "manual return from Booster",
    )

    rt = load_runtime()
    for tab in tabs:
        rt_tab = get_runtime_tab(rt, tab.get("package"))
        market_clear_booster_route(rt_tab)
        rt_tab["target"] = "market"
    save_runtime(rt)
    return ok, note


