def booster_probe_path_candidates(prof, state=None):
    """Resolve exact Booster scanner JSON candidates without package aliasing."""
    candidates = []
    seen = set()

    def add(path):
        if not path:
            return
        item = Path(str(path))
        key = str(item)
        if key not in seen:
            seen.add(key)
            candidates.append(item)

    explicit = str(prof.get("probe_file") or "").strip()
    if explicit:
        add(explicit)

    state_file = str(prof.get("state_file") or "").strip()
    state_parent = Path(state_file).parent if state_file else None

    names = []
    for value in (
        (state or {}).get("username") if isinstance(state, dict) else "",
        prof.get("booster_name"),
    ):
        text = str(value or "").strip()
        if text and text not in names:
            names.append(text)

    if state_file:
        stem = Path(state_file).stem
        if stem.endswith("_state"):
            stem = stem[:-6]
        if stem and stem != "state" and stem not in names:
            names.append(stem)

    for name in names:
        filename = f"{_sanitize_state_name(name)}_booster_probe.json"
        if state_parent:
            add(state_parent / filename)
        if is_delta_global_tab({
            "state_file": state_file,
            "executor_storage": prof.get("executor_storage", ""),
        }):
            add(DELTA_GLOBAL_STATE_DIR / filename)

    return candidates


def _booster_probe_read_json(path):
    try:
        payload = json.loads(Path(path).read_text(encoding="utf-8"))
    except Exception as exc:
        return None, str(exc)

    if not isinstance(payload, dict):
        return None, "probe JSON is not an object"

    payload = dict(payload)
    ts = int(payload.get("ts", 0) or 0)
    payload["age"] = now() - ts if ts > 0 else 999999
    payload["_path"] = str(path)
    return payload, None


def booster_read_probe(prof, state=None, bcfg=None):
    """Read the freshest exact-identity Booster scanner JSON."""
    bcfg = load_booster_config() if bcfg is None else bcfg
    if not bcfg.get("probe_enabled", True):
        return None, "disabled"

    expected_names = {
        _delta_username_key(value)
        for value in (
            (state or {}).get("username") if isinstance(state, dict) else "",
            prof.get("booster_name"),
        )
        if _usable_detected_username(value)
    }

    candidates = booster_probe_path_candidates(prof, state)
    parents = []
    parent_seen = set()
    for path in candidates:
        key = str(path.parent)
        if key not in parent_seen:
            parent_seen.add(key)
            parents.append(path.parent)

    readable = []
    errors = []
    considered = set()

    def consider(path):
        path = Path(path)
        key = str(path)
        if key in considered:
            return
        considered.add(key)
        if not path.exists():
            return
        payload, err = _booster_probe_read_json(path)
        if err:
            errors.append(f"{path.name}: {err}")
            return
        actual_key = _delta_username_key(payload.get("username"))
        if expected_names and actual_key and actual_key not in expected_names:
            return
        readable.append(payload)

    for path in candidates:
        consider(path)

    if not readable:
        for parent in parents:
            try:
                files = list(parent.glob("*_booster_probe.json"))
            except Exception:
                files = []
            for path in files:
                consider(path)

    if not readable:
        if errors:
            return None, "; ".join(errors[:3])
        return None, "missing"

    readable.sort(
        key=lambda item: (
            int(item.get("ts", 0) or 0),
            int(item.get("write_seq", 0) or 0),
        ),
        reverse=True,
    )
    return readable[0], None


def booster_probe_quality(probe, err, bcfg):
    if not bcfg.get("probe_enabled", True):
        return "disabled", True, "probe disabled by config"
    if not isinstance(probe, dict):
        return "missing", False, str(err or "missing")

    probe_error = str(probe.get("error") or "").strip()
    if probe_error:
        return "error", False, probe_error
    if not probe.get("supported_place", True):
        return "wrong_place", False, "outside Booster place"

    age = int(probe.get("age", 999999) or 999999)
    stale_after = max(
        20,
        int(bcfg.get("probe_stale_seconds", 90) or 90),
    )
    if age > stale_after:
        return "stale", False, f"{age}s old"

    if not probe.get("probe_ready", False):
        return "waiting", False, "scanner not ready"

    inventory = int(
        probe.get("inventory_entry_count", 0) or 0
    )
    parsed = int(
        probe.get("parsed_pet_count", 0) or 0
    )
    missing = probe.get("missing_fields", {})
    if not isinstance(missing, dict):
        missing = {}

    missing_age = int(
        missing.get("age", 0) or 0
    )
    missing_weight = int(
        missing.get("base_weight", 0) or 0
    )

    # Data integrity is authoritative. This rejects the original broken probe
    # that parsed names but missed every age/weight field, regardless of what
    # schema number it claimed.
    if (
        parsed != inventory
        or missing_age > 0
        or missing_weight > 0
    ):
        return (
            "incomplete",
            False,
            f"parsed {parsed}/{inventory}; "
            f"missing age {missing_age}, weight {missing_weight}",
        )

    expected_schema = int(
        bcfg.get(
            "probe_expected_schema_version",
            2,
        )
        or 2
    )
    schema = int(
        probe.get("schema_version", 0) or 0
    )

    # Some already-running verified v0.1.1 writers retained schema 0/1 while
    # producing the complete PetData.Level/BaseWeight payload. Accept those
    # contents instead of hiding valid Booster matches behind a metadata-only
    # mismatch.
    if schema < expected_schema:
        revision = str(
            probe.get("probe_revision") or ""
        ).strip()
        suffix = (
            f"; schema {schema} compatibility"
            + (
                f" ({revision})"
                if revision
                else ""
            )
        )
        return (
            "ready",
            True,
            f"{parsed} pets parsed{suffix}",
        )

    return "ready", True, f"{parsed} pets parsed"



def booster_health_state_from_probe(
    state,
    probe,
    probe_status,
    probe_reportable,
    package_alive_now,
    bcfg,
):
    """Create an in-memory clean heartbeat from a verified fresh probe.

    This never writes over the normal state file. It only prevents a stale or
    missing v3.9 file from restarting a package whose verified Booster scanner
    is actively executing in the expected game.
    """
    enabled = bool(
        bcfg.get(
            "probe_health_fallback_enabled",
            True,
        )
    )
    ready = bool(
        enabled
        and package_alive_now
        and probe_status == "ready"
        and probe_reportable
        and isinstance(probe, dict)
    )
    if not ready:
        return state, False, ""

    merged = dict(state or {})

    # A currently executing scanner in Main Garden proves old Lua popup flags
    # are stale. Clear them only in this temporary health copy. Android's
    # package-scoped disconnect detector still runs first and can override it.
    for key in (
        "disconnected",
        "_android_disconnect_confirmed",
        "disconnect_title",
        "disconnect_text",
        "disconnect_code",
        "disconnect_reason",
        "disconnect_observed_ts",
        "login_challenge",
        "login_challenge_text",
        "login_challenge_reason",
        "ui_title",
        "ui_text",
        "popup_title",
        "popup_text",
        "screen_text",
        "text",
        "note",
    ):
        merged.pop(key, None)

    probe_age = max(
        0,
        int(probe.get("age", 0) or 0),
    )
    probe_ts = int(
        probe.get("ts", now()) or now()
    )
    inventory = int(
        probe.get(
            "parsed_pet_count",
            probe.get("inventory_entry_count", 0),
        )
        or 0
    )

    merged["age"] = probe_age
    merged["ts"] = probe_ts
    merged["state_ts"] = probe_ts
    merged["updated_at"] = probe_ts
    merged["place_id"] = str(
        probe.get("place_id")
        or merged.get("place_id")
        or ""
    )
    merged["username"] = str(
        probe.get("username")
        or merged.get("username")
        or ""
    )
    merged["pet_count"] = inventory
    merged["_booster_probe_health"] = True
    merged["_booster_probe_revision"] = str(
        probe.get("probe_revision") or ""
    )

    if state:
        normal_age = state_age_seconds(state)
        if normal_age >= 999999:
            note = (
                f"fresh probe {probe_age}s; "
                "normal state invalid/missing timestamp"
            )
        else:
            note = (
                f"fresh probe {probe_age}s; "
                f"normal state old {format_age(normal_age)}"
            )
    else:
        note = (
            f"fresh probe {probe_age}s; "
            "normal state missing"
        )

    return merged, True, note


def booster_probe_matches(probe, bcfg):
    """Return compact verified valuable-pet records for D1."""
    if not isinstance(probe, dict):
        return []
    raw = probe.get("valuable_pets", [])
    if not isinstance(raw, list):
        return []

    min_age = int(probe.get("min_age", 500) or 500)
    min_weight = float(probe.get("min_age1_base_weight_kg", 6.0) or 6.0)
    limit = max(1, int(bcfg.get("probe_max_report_pets", 250) or 250))

    output = []
    for item in raw:
        if not isinstance(item, dict):
            continue
        age_value = item.get("age")
        age = int(age_value) if isinstance(age_value, (int, float)) else None
        age0_value = item.get("base_weight_age0_kg")
        age1_value = item.get("base_weight_age1_kg")
        age0 = float(age0_value) if isinstance(age0_value, (int, float)) else None
        age1 = float(age1_value) if isinstance(age1_value, (int, float)) else None

        reasons = []
        if age is not None and age >= min_age:
            reasons.append("age")
        if age1 is not None and age1 >= min_weight:
            reasons.append("weight")
        if not reasons:
            continue

        mutations = item.get("mutations", [])
        if not isinstance(mutations, list):
            mutations = []
        output.append({
            "uuid": str(item.get("uuid") or ""),
            "name": str(item.get("name") or ""),
            "age": age,
            "base_weight_kg": age1,
            "base_weight_age0_kg": age0,
            "base_weight_age1_kg": age1,
            "mutation": str(item.get("mutation") or "Normal"),
            "mutations": [str(value) for value in mutations],
            "is_favorite": bool(item.get("is_favorite", False)),
            "hatched_from": str(item.get("hatched_from") or ""),
            "boost_count": int(item.get("boost_count", 0) or 0),
            "valuable_reasons": reasons,
        })

    output.sort(
        key=lambda item: (
            -float(item.get("base_weight_age1_kg") or -1),
            -int(item.get("age") or -1),
            str(item.get("name") or "").lower(),
            str(item.get("uuid") or ""),
        )
    )
    return output[:limit]

def load_booster_runtime():
    rt = load_json(BOOSTER_RUNTIME_FILE, {})
    for key in ("last_update_ts", "last_signature", "last_status"):
        if not isinstance(rt.get(key), dict):
            rt[key] = {}
    return rt


def save_booster_runtime(rt):
    save_json(BOOSTER_RUNTIME_FILE, rt)



def booster_entry(prof, state, err, probe=None, probe_err=None, bcfg=None):
    bcfg = load_booster_config() if bcfg is None else bcfg
    link = str(prof.get("server_link") or "").strip()
    (
        private_route_link,
        private_place_id,
        private_link_code,
        private_access_code,
    ) = normalized_private_route_link(
        link,
        record={
            "place_id": (
                (state or {}).get("place_id")
                or (probe or {}).get("place_id")
                or "126884695634066"
            ),
        },
        default_place_id="126884695634066",
    )
    probe_status, probe_reportable, probe_note = booster_probe_quality(probe, probe_err, bcfg)
    matches = booster_probe_matches(probe, bcfg) if probe_reportable else []

    if not prof.get("enabled", True):
        status = "disabled"
    elif not link or link.startswith(("YOUR_", "PUT_")):
        status = "no_server"
    elif probe_reportable:
        status = "available" if matches else "online"
    elif not state:
        status = "no_state"
    else:
        status = "probe_wait"

    entry = {
        "enabled": bool(prof.get("enabled", True)),
        "package": prof.get("package", ""),
        "name": prof.get("booster_name", ""),
        "booster_name": prof.get("booster_name", ""),
        "mode": "booster",
        "role": "booster",
        "status": status,
        "server_link": private_route_link or link,
        "private_server_place_id": private_place_id,
        "private_server_link_code": private_link_code,
        "private_server_access_code": private_access_code,
        "private_route_ready": bool(
            private_route_link
            and (
                private_link_code
                or private_access_code
            )
        ),
        "pet_count": int(
            (state or {}).get(
                "pet_count",
                (probe or {}).get(
                    "parsed_pet_count",
                    (probe or {}).get("inventory_entry_count", 0),
                ),
            )
            or 0
        ),
        "egg_total": int((state or {}).get("egg_total", 0) or 0),
        "boosting_match_count": len(matches),
        "boosting_matches": matches,
        "boosting_min_base_weight_kg": float((probe or {}).get("min_age1_base_weight_kg", 6.0) or 6.0),
        "boosting_min_age": int((probe or {}).get("min_age", 500) or 500),
        "boosting_weight_mode": str((probe or {}).get("weight_mode", "BaseWeight age-0 multiplied by 1.1")),
        "boosting_weight_precision": str((probe or {}).get("weight_precision", "truncate_2_decimals_no_rounding")),
        "booster_probe_status": probe_status,
        "booster_probe_reportable": bool(probe_reportable),
        "booster_probe_note": probe_note,
        "booster_probe_revision": str((probe or {}).get("probe_revision", "")),
        "booster_probe_schema_version": int((probe or {}).get("schema_version", 0) or 0),
        "booster_probe_ts": int((probe or {}).get("ts", 0) or 0),
        "booster_probe_age": int((probe or {}).get("age", 999999) or 999999),
        "booster_probe_file": str((probe or {}).get("_path", prof.get("probe_file", ""))),
        "booster_probe_inventory_count": int((probe or {}).get("inventory_entry_count", 0) or 0),
        "booster_probe_parsed_count": int((probe or {}).get("parsed_pet_count", 0) or 0),
        "booster_probe_missing_fields": (
            (probe or {}).get("missing_fields", {})
            if isinstance((probe or {}).get("missing_fields", {}), dict)
            else {}
        ),
        "updated_at": now(),
        "updated_text": date_time_text(),
        "source": "nomo_rejoin_booster_phase2",
    }
    identity_source = {}
    if isinstance(probe, dict):
        identity_source.update({
            "username": probe.get("username"),
            "place_id": probe.get("place_id"),
            "job_id": probe.get("job_id"),
        })
    if isinstance(state, dict):
        for key in (
            "username",
            "place_id",
            "job_id",
            "state_ts",
        ):
            value = state.get(key)
            if value not in (None, ""):
                identity_source[key] = value

    for key in (
        "username",
        "place_id",
        "job_id",
        "state_ts",
    ):
        value = identity_source.get(key)
        if value not in (None, ""):
            entry[key] = value

    entry["booster_job_id"] = str(
        entry.get("job_id") or ""
    )

    if state:
        entry["state_age"] = state.get("age")
    else:
        entry["error"] = str(err or "no state")
    return entry


def booster_signature(entry):
    compact_matches = []
    raw_matches = entry.get("boosting_matches", [])
    if not isinstance(raw_matches, list):
        raw_matches = []
    for item in raw_matches:
        if not isinstance(item, dict):
            continue
        compact_matches.append({
            "uuid": item.get("uuid"),
            "name": item.get("name"),
            "age": item.get("age"),
            "base_weight_age0_kg": item.get("base_weight_age0_kg"),
            "base_weight_age1_kg": item.get("base_weight_age1_kg"),
            "mutation": item.get("mutation"),
            "valuable_reasons": item.get("valuable_reasons"),
        })
    return json.dumps({
        "enabled": entry.get("enabled"),
        "status": entry.get("status"),
        "server_link": entry.get("server_link"),
        "job_id": entry.get("job_id"),
        "probe_revision": entry.get("booster_probe_revision"),
        "matches": compact_matches,
    }, sort_keys=True, separators=(",", ":"))

def booster_should_update(bcfg, name, entry, force=False):
    if force:
        return True, "forced"
    rt = load_booster_runtime()
    sig = booster_signature(entry)
    last = str(rt["last_signature"].get(name, ""))
    last_ts = int(rt["last_update_ts"].get(name, 0) or 0)
    force_every = int(bcfg.get("force_update_every_seconds", 3600) or 3600)
    if not bcfg.get("update_only_on_status_change", True) or sig != last:
        return True, "changed"
    if now() - last_ts >= force_every:
        return True, "heartbeat"
    return False, "unchanged"



def _cloudflare_booster_tombstone_entry(entry, status, name=""):
    tombstone = dict(entry or {})
    name = str(name or tombstone.get("booster_name") or tombstone.get("name") or "booster").strip() or "booster"
    tombstone["enabled"] = False
    tombstone["status"] = str(status or "disabled")
    tombstone["server_link"] = ""
    tombstone["boosting_matches"] = []
    tombstone["boosting_match_count"] = 0
    tombstone["mode"] = "booster"
    tombstone["role"] = "booster"
    tombstone["booster_name"] = name
    tombstone["name"] = name
    tombstone["updated_at"] = now()
    tombstone["updated_text"] = date_time_text()
    tombstone.setdefault("source", "nomo_rejoin_booster_tombstone")
    return tombstone


def _cloudflare_booster_tombstone_due(bcfg, profile_name, tombstone, force=False):
    # Booster tombstones are state changes, not heartbeats. Once a given
    # disabled/no_server signature was sent successfully, do not resend it on
    # every reporter loop. Explicit force/report tests may intentionally resend.
    if force:
        return True
    rt = load_booster_runtime()
    sig = booster_signature(tombstone)
    last_sig = str(rt.get("last_signature", {}).get(profile_name, ""))
    return sig != last_sig


def _update_booster_runtime_entry(rt, name, entry):
    rt["last_update_ts"][name] = now()
    rt["last_signature"][name] = booster_signature(entry)
    rt["last_status"][name] = entry.get("status")


def booster_report_once(bcfg=None, force=False, state_cache=None):
    bcfg = load_booster_config() if bcfg is None else bcfg
    if not bcfg.get("enabled", True):
        return False, "booster mode disabled"
    if hatcher_backend_missing(bcfg):
        return False, "backend missing"

    provider = backend_provider(bcfg)
    updates = []
    removes = []  # legacy/JSONBin removal path only
    cloudflare_tombstones = []
    probe_waiting = []
    skips = []
    brt = load_booster_runtime()
    profiles = booster_profiles_with_hatcher_routing(
        bcfg,
        load_hatcher_config(),
        enabled_only=False,
    )
    current_profile_names = {
        str(profile.get("booster_name") or "booster")
        for profile in profiles
    }
    pending_identity_removes = [
        name
        for name in _unique_identity_names(brt.get("pending_remove_names", []))
        if name not in current_profile_names
    ]

    # A renamed Booster identity must be retired once. On Cloudflare publish a
    # Booster-shaped tombstone so role/mode remain correct; JSONBin keeps its
    # original delete semantics.
    if provider == "cloudflare":
        for name in pending_identity_removes:
            cloudflare_tombstones.append((
                name,
                _cloudflare_booster_tombstone_entry({}, "renamed", name=name),
                "renamed",
            ))
    else:
        removes.extend((name, "renamed") for name in pending_identity_removes)

    if brt.get("mapping_force_report"):
        force = True

    for prof in profiles:
        name = str(prof.get("booster_name") or "booster")
        pkg = str(prof.get("package") or "")
        state = None
        err = "missing"
        probe = None
        probe_err = "missing"

        cached = state_cache.get(pkg) if isinstance(state_cache, dict) else None
        if isinstance(cached, dict):
            state = cached.get("state")
            err = cached.get("state_err")
            probe = cached.get("probe")
            probe_err = cached.get("probe_err")
        elif isinstance(cached, tuple) and len(cached) == 2:
            state, err = cached
        else:
            state, err = booster_read_state(prof)

        if probe is None and probe_err in (None, "missing"):
            probe, probe_err = booster_read_probe(prof, state=state, bcfg=bcfg)

        entry = booster_entry(
            prof, state, err,
            probe=probe,
            probe_err=probe_err,
            bcfg=bcfg,
        )
        status = str(entry.get("status") or "").lower()

        # Match Hatcher's proven Cloudflare semantics: a temporary missing
        # state must never erase a previously-good Booster route. Let backend
        # staleness age it naturally while NOMO recovery handles the package.
        if provider == "cloudflare" and status == "no_state":
            skips.append(f"{name}:no_state-preserve")
            continue

        # disabled/no_server become Booster-shaped tombstones and are sent only
        # when their signature changes. This prevents a 60s removal heartbeat.
        if provider == "cloudflare" and status in ("disabled", "no_server"):
            tombstone = _cloudflare_booster_tombstone_entry(entry, status, name=name)
            if _cloudflare_booster_tombstone_due(
                bcfg, name, tombstone, force=bool(force)
            ):
                cloudflare_tombstones.append((name, tombstone, status))
            else:
                skips.append(f"{name}:{status}-unchanged")
            continue

        # Preserve the original JSONBin behavior outside Cloudflare.
        if status in ("disabled", "no_server", "no_state"):
            removes.append((name, status))
            continue

        if bcfg.get("probe_required_for_report", True) and not entry.get("booster_probe_reportable", False):
            probe_waiting.append((name, entry.get("booster_probe_status", "missing")))
            continue

        should, _reason = booster_should_update(bcfg, name, entry, force=force)
        if should:
            updates.append((name, entry))
        else:
            skips.append(f"{name}:unchanged")

    if not updates and not removes and not cloudflare_tombstones:
        if probe_waiting:
            detail = ", ".join(f"{name}:{status}" for name, status in probe_waiting[:4])
            return True, f"waiting for Booster probe ({detail})"
        if skips:
            return True, "no update; " + ", ".join(skips[:4])
        return True, "no update; unchanged"

    if provider == "cloudflare":
        # Use the same global/persistent Cloudflare upload hold as Hatcher.
        # Tombstones are sent through the normal update endpoint so they keep
        # mode=booster instead of being rewritten as Hatcher removals.
        upload_pairs = list(updates) + [
            (name, tombstone)
            for name, tombstone, status in cloudflare_tombstones
        ]
        ok, msg = cloudflare_update_hatchers(bcfg, upload_pairs, [])
        if not ok:
            return False, f"cloudflare update: {msg}"

        # The shared upload helper intentionally returns OK while a persistent
        # 429/1027 cooldown is active. Do NOT stamp signatures or clear renamed
        # identities until the data really reached Cloudflare.
        msg_lower = str(msg or "").lower()
        if "cooldown" in msg_lower or "rate limited" in msg_lower:
            return True, msg

        rt = load_booster_runtime()
        for name, entry in updates:
            _update_booster_runtime_entry(rt, name, entry)
        for name, tombstone, status in cloudflare_tombstones:
            _update_booster_runtime_entry(rt, name, tombstone)
        save_booster_runtime(rt)
        _clear_booster_pending_identity_removes(pending_identity_removes)

        waiting_note = f"; probe waiting {len(probe_waiting)}" if probe_waiting else ""
        return True, (
            f"cloudflare updated {len(updates)} "
            f"tombstoned {len(cloudflare_tombstones)}{waiting_note}"
        )

    # JSONBin path intentionally preserves the pre-V4.81.12 behavior.
    record, err = jsonbin_read_bin(bcfg)
    if err:
        return False, err
    record = record if isinstance(record, dict) else {}
    pool = record.setdefault("hatchers", {})
    for name, _status in removes:
        pool.pop(name, None)
    for name, entry in updates:
        pool[name] = entry
    ok, msg = jsonbin_update_bin(bcfg, record)
    if not ok:
        return False, msg

    rt = load_booster_runtime()
    for name, entry in updates:
        _update_booster_runtime_entry(rt, name, entry)
    save_booster_runtime(rt)
    _clear_booster_pending_identity_removes(pending_identity_removes)
    waiting_note = f"; probe waiting {len(probe_waiting)}" if probe_waiting else ""
    return True, f"updated {len(updates)} removed {len(removes)}{waiting_note}"

def booster_status_screen(rows, bcfg, cfg, session_start, loops, last_msg=""):
    clear(); print_banner(cfg)
    print(col("BOOSTER MODE — stay in server; Market joins Booster", MAGENTA))
    print(col(f"Backend: {last_msg}", DIM))
    table_rows = []
    for row in rows:
        table_rows.append([
            (row.get("user", ""), WHITE), (short_pkg(row.get("pkg", "")), CYAN),
            (str(row.get("pets", "-")), WHITE, True), (str(row.get("matches", "-")), MAGENTA, True),
            (row.get("status", ""), status_color(row.get("status", ""))),
            (str(row.get("age", "-")), DIM), (row.get("session", ""), DIM),
            (row.get("note", ""), note_color(row.get("note", ""))),
        ])
    draw_table(["User", "Pkg", "Pets", "Boost", "Status", "Age", "Session", "Note"],
               table_rows, [14, 8, 5, 5, 10, 6, 9, 28], cfg)
    print(col(f"Uptime {format_uptime(now()-session_start)} | checks {loops} | Q+ENTER stops", DIM))
    render_activity_log(cfg, int(cfg.get("activity_log_lines", 6) or 6))





def _booster_hatcher_report_adapter(
    hcfg,
    force=False,
    state_cache=None,
    main_runtime=None,
):
    bcfg = load_booster_config()
    profiles = booster_profiles_with_hatcher_routing(
        bcfg,
        hcfg,
        enabled_only=False,
    )
    state_cache = (
        state_cache
        if isinstance(state_cache, dict)
        else {}
    )

    converted = {}
    for profile in profiles:
        package = str(profile.get("package") or "")
        cached = state_cache.get(package)

        state = None
        state_err = "missing"
        if isinstance(cached, tuple) and len(cached) == 2:
            state, state_err = cached
        elif isinstance(cached, dict):
            state = cached.get("state")
            state_err = cached.get("state_err")
        else:
            state, state_err = booster_read_state(profile)

        probe, probe_err = booster_read_probe(
            profile,
            state=state,
            bcfg=bcfg,
        )
        converted[package] = {
            "state": state,
            "state_err": state_err,
            "probe": probe,
            "probe_err": probe_err,
        }

    return booster_report_once(
        bcfg,
        force=force,
        state_cache=converted,
    )


def _booster_hatcher_dashboard_adapter(
    rows,
    hcfg,
    cfg,
    session_start,
    loops,
    last_msg="",
):
    bcfg = load_booster_config()
    profiles = {
        str(profile.get("package") or ""): profile
        for profile in booster_profiles_with_hatcher_routing(
            bcfg,
            hcfg,
            enabled_only=False,
        )
    }

    output = []
    for row in rows:
        package = str(row.get("pkg") or "")
        profile = profiles.get(package)
        matches = "-"
        probe_note = "probe profile missing"

        if isinstance(profile, dict):
            state, _ = booster_read_state(profile)
            probe, probe_err = booster_read_probe(
                profile,
                state=state,
                bcfg=bcfg,
            )
            (
                probe_status,
                probe_reportable,
                quality_note,
            ) = booster_probe_quality(
                probe,
                probe_err,
                bcfg,
            )

            if probe_reportable:
                matches = len(
                    booster_probe_matches(
                        probe,
                        bcfg,
                    )
                )
                probe_note = (
                    f"probe ready; {matches} valuable"
                )
            else:
                probe_note = (
                    f"probe {probe_status}: {quality_note}"
                )

        note = "; ".join(
            value
            for value in (
                str(row.get("note") or "").strip(),
                "shared keep-alive core",
                probe_note,
            )
            if value
        )

        output.append({
            "user": row.get("user", ""),
            "pkg": package,
            "pets": row.get("pets", "-"),
            "matches": matches,
            "status": row.get("status", ""),
            "age": row.get("age", "-"),
            "session": row.get("session", ""),
            "note": note,
        })

    booster_status_screen(
        output,
        bcfg,
        cfg,
        session_start,
        loops,
        last_msg,
    )
    print(
        col(
            "  Core: shared keep-alive engine; "
            "Booster dashboard/report/probe adapters active.",
            GREEN,
        )
    )



def start_booster_safe_rejoiner(main_cfg=None):
    """Shared keep-alive start with Booster-only output adapters."""
    cfg = dict(load_config())
    if isinstance(main_cfg, dict):
        cfg.update(main_cfg)

    # Refresh only mappings/identity. Existing Hatcher server_link values are
    # preserved by sync_hatcher_profiles_with_tabs().
    hcfg = load_hatcher_config()
    sync_hatcher_profiles_with_tabs(
        cfg,
        hcfg,
        create_missing=True,
    )
    hcfg = load_hatcher_config()
    hcfg["enabled"] = True
    save_hatcher_config(hcfg)

    # Booster config is report/probe identity only.
    bcfg = load_booster_config()
    sync_booster_profiles_with_tabs(
        cfg,
        bcfg,
        create_missing=True,
    )

    original_report = globals()[
        "hatcher_report_once"
    ]
    original_dashboard = globals()[
        "hatcher_rejoin_status_screen"
    ]

    globals()["hatcher_report_once"] = (
        _booster_hatcher_report_adapter
    )
    globals()["hatcher_rejoin_status_screen"] = (
        _booster_hatcher_dashboard_adapter
    )

    try:
        return start_hatcher_safe_rejoiner(
            cfg
        )
    finally:
        globals()["hatcher_report_once"] = (
            original_report
        )
        globals()[
            "hatcher_rejoin_status_screen"
        ] = original_dashboard







