def open_all_hatcher_tabs_once(
    main_cfg=None,
    selected_packages=None,
):
    """Exact Hatcher Option 6 path, shared unchanged by Booster."""
    cfg = dict(load_config())
    if isinstance(main_cfg, dict):
        cfg.update(main_cfg)

    hcfg = load_hatcher_config()
    selected = [
        str(package or "")
        for package in (selected_packages or [])
        if str(package or "")
    ]

    profile_by_package = {
        str(profile.get("package") or ""): profile
        for profile in hatcher_profiles(
            hcfg,
            enabled_only=False,
        )
    }

    tabs = []
    skipped = []

    for package in selected:
        profile = profile_by_package.get(package)

        if not isinstance(profile, dict):
            skipped.append(
                (package, "no Hatcher/Booster profile or account")
            )
            continue

        if not profile.get("enabled", True):
            skipped.append(
                (package, "Hatcher/Booster profile is OFF")
            )
            continue

        raw_link = str(profile.get("server_link") or "").strip()
        if not raw_link:
            skipped.append(
                (package, "Hatcher server_link is empty")
            )
            continue

        tabs.append(hatcher_profile_to_tab(
            profile,
            hcfg=hcfg,
            cfg=cfg,
            refresh_vip=True,
        ))

    if skipped:
        print(col("Skipped selected packages:", YELLOW))
        for package, reason in skipped:
            print(
                f"  {short_pkg(package):<10} "
                f"{col(reason, RED)}"
            )
        print("")

    if not tabs:
        print(
            col(
                "No selected package has an enabled "
                "Hatcher/Booster profile with a saved server link.",
                RED,
            )
        )
        pause()
        return False

    hcfg["hatchers"] = [
        normalize_hatcher_profile(profile, index)
        for index, profile in enumerate(hatcher_profiles(hcfg, enabled_only=False))
    ]
    save_hatcher_config(hcfg)

    run_startup_cache_cleanup(
        cfg,
        selected_packages=[
            str(tab.get("package") or "")
            for tab in tabs
        ],
        reason="Option 6 Hatcher/Booster force restart",
        show_screen=True,
        setting_key="clear_cache_before_option6_restart",
        screen_title="OPTION 6: CACHE CLEANUP",
    )

    print(
        col(
            "Option 6: same post-open recovery chain as Option 1.",
            CYAN,
        )
    )
    print(
        col(
            "Saved Hatcher private route is rebuilt from joinCode when available.",
            GREEN,
        )
    )

    ok = manual_restart_tabs_via_queue(
        cfg,
        tabs,
        "hatcher",
        "manual hatcher/booster force restart",
    )

    verify_option6_open_results(cfg, tabs, "Hatcher/Booster tab(s)")
    pause()
    return bool(ok)




