def exotic_status_for_username(username):
    wanted = str(username or "").strip().lower()
    if not wanted:
        return None
    best = None
    best_ts = -1
    for payload in _exotic_status_files():
        if str(payload.get("username") or "").strip().lower() != wanted:
            continue
        try:
            ts = int(payload.get("ts", 0) or 0)
        except Exception:
            ts = 0
        if ts >= best_ts:
            best = payload
            best_ts = ts
    if not best:
        return None
    result = dict(best)
    result["age"] = max(0, now() - max(0, best_ts)) if best_ts > 0 else 999999
    return result


def exotic_status_note_for_username(
    username, cfg, current_job_id="", current_job_seen_age=None
):
    """Return a package-facing Exotic health note for the current Roblox server.

    V4.81.15 binds EXOTIC_STARTED to the current state job_id. A stale status
    from the previous server can no longer make a fresh rejoin look healthy.
    """
    status = exotic_status_for_username(username)
    expected_job = str(current_job_id or "").strip()
    warn_after = max(60, int(cfg.get("exotic_key_status_warn_after_seconds", 180) or 180))
    try:
        seen_age = int(current_job_seen_age) if current_job_seen_age is not None else None
    except Exception:
        seen_age = None

    if not status:
        if expected_job and seen_age is not None:
            if seen_age >= warn_after:
                return "EXOTIC FAILED current server has no status"
            return f"EXOTIC waiting current server {max(0, warn_after - seen_age)}s"
        return ""

    stage = str(status.get("stage") or "").strip().upper()
    age = int(status.get("age", 999999) or 999999)
    err = cut(str(status.get("error") or ""), 70)
    status_job = str(status.get("job_id") or status.get("jobId") or "").strip()

    if expected_job:
        current_match = bool(status_job) and status_job == expected_job
        if not current_match:
            if seen_age is not None and seen_age >= warn_after:
                return "EXOTIC FAILED current server unconfirmed"
            if seen_age is not None:
                return f"EXOTIC waiting current server {max(0, warn_after - seen_age)}s"
            return "EXOTIC current server unconfirmed"

    failures = {
        "KEY_MISSING",
        "EXOTIC_DOWNLOAD_FAILED",
        "EXOTIC_COMPILE_FAILED",
        "EXOTIC_SOURCE_UNAVAILABLE",
        "EXOTIC_RUNTIME_FAILED",
    }
    if stage in failures:
        return "EXOTIC " + stage.replace("EXOTIC_", "") + (f": {err}" if err else "")
    if stage and stage != "EXOTIC_STARTED" and age >= warn_after:
        return f"EXOTIC {stage} stuck {format_age(age)}"
    if stage == "EXOTIC_STARTED" and bool(cfg.get("exotic_key_status_show_ok", False)):
        return f"Exotic OK {format_age(age)}"
    return ""


def exotic_key_generation_id(state=None):
    """Stable non-secret ID for the currently cached Exotic key."""
    if state is None:
        state = load_exotic_key_state()
    key = _exotic_clean_key((state or {}).get("key"))
    if not key:
        return ""
    return hashlib.sha256(key.encode("utf-8", "ignore")).hexdigest()[:16]


def exotic_note_needs_recovery(note):
    """True only for current-server Exotic states that cannot be left running."""
    text = str(note or "").strip().upper()
    if not text.startswith("EXOTIC"):
        return False
    markers = (
        "FAILED",
        "KEY_MISSING",
        "KEY MISSING",
        "SOURCE_UNAVAILABLE",
        "SOURCE UNAVAILABLE",
        " STUCK ",
    )
    return any(marker in text for marker in markers)


def exotic_status_started_for_current_job(username, current_job_id):
    status = exotic_status_for_username(username)
    if not status:
        return False
    if str(status.get("stage") or "").strip().upper() != "EXOTIC_STARTED":
        return False
    expected = str(current_job_id or "").strip()
    if not expected:
        return True
    actual = str(status.get("job_id") or status.get("jobId") or "").strip()
    return bool(actual) and actual == expected


def exotic_key_import_legacy_config(cfg):
    candidates = [
        BASE_DIR / "key_cloudflare.json",
        Path("/storage/emulated/0/Download/key_cloudflare.json"),
        Path("/storage/emulated/0/key_cloudflare.json"),
    ]
    for path in candidates:
        try:
            if not path.exists():
                continue
            data = json.loads(path.read_text(encoding="utf-8"))
            if not isinstance(data, dict):
                continue
            secret = str(data.get("write_secret") or "").strip()
            worker = str(data.get("worker_url") or "").strip()
            token = str(data.get("read_token") or "").strip()
            if worker:
                cfg["exotic_key_worker_url"] = worker.rstrip("/")
            if secret:
                cfg["exotic_key_write_secret"] = secret
            if token:
                cfg["exotic_key_read_token"] = token
            if secret:
                cfg["exotic_key_writer_enabled"] = True
                cfg["exotic_key_manager_enabled"] = True
            save_config(cfg)
            return True, str(path)
        except Exception:
            continue
    return False, "legacy key_cloudflare.json not found"


def _exotic_menu_time(value):
    try:
        ts = int(value or 0)
    except Exception:
        ts = 0
    if ts <= 0:
        return "-"
    try:
        return datetime.fromtimestamp(ts).strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return str(ts)


def _exotic_menu_wait(value):
    try:
        ts = int(value or 0)
    except Exception:
        ts = 0
    if ts <= 0:
        return "-"
    left = ts - now()
    if left <= 0:
        return "NOW"
    return "in " + format_age(left)


def _exotic_writer_readiness(cfg, state):
    manager = bool(cfg.get("exotic_key_manager_enabled", True))
    writer = bool(cfg.get("exotic_key_writer_enabled", False))
    secret = str(cfg.get("exotic_key_write_secret", "") or "").strip()
    worker = _exotic_worker_base(cfg)
    if not writer:
        return "OFF", DIM
    if _protected_json_health(EXOTIC_KEY_STATE_FILE).get("status") == "corrupt":
        return "BLOCKED - LOCAL KEY STATE CORRUPT", RED
    if not manager:
        return "BLOCKED - KEY MANAGER OFF", RED
    if not worker.startswith("https://"):
        return "BLOCKED - WORKER URL INVALID", RED
    if not secret:
        return "BLOCKED - WRITER SECRET MISSING", RED
    with _EXOTIC_KEY_JOB_LOCK:
        running = bool(_EXOTIC_KEY_JOB.get("running"))
        mode = str(_EXOTIC_KEY_JOB.get("mode") or "").upper()
    if running:
        return f"BUSY - {mode or 'BACKGROUND JOB'}", CYAN
    if bool(state.get("writer_conflict_suspected", False)):
        return "BLOCKED - WRITER CONFLICT / CLOUD KEY DIFFERS", RED
    retry_at = int(state.get("next_writer_retry_at", 0) or 0)
    if retry_at > now():
        err = str(state.get("last_cloud_error") or state.get("last_writer_error") or "")
        if _exotic_rate_limited_text(err):
            return f"CLOUD RATE-LIMITED - RETRY {_exotic_menu_wait(retry_at)}", YELLOW
        return f"RETRY WAIT - {_exotic_menu_wait(retry_at)}", YELLOW
    key = _exotic_clean_key(state.get("key"))
    if not key:
        return "READY - NEW KEY WILL GENERATE", GREEN
    if bool(state.get("cloud_pending", False)):
        return "READY - LOCAL KEY OK, CLOUD UPLOAD PENDING", YELLOW
    refresh_at = int(state.get("refresh_at", 0) or 0)
    if refresh_at <= 0 or refresh_at <= now():
        return "READY - KEY REFRESH DUE NOW", GREEN
    return f"ACTIVE - NEXT GENERATION {_exotic_menu_wait(refresh_at)}", GREEN


def exotic_key_settings_menu(cfg):
    # V4.81.50: this menu used to block indefinitely inside input(), freezing both
    # the visible countdowns and the normal Exotic manager tick.  Keep the menu
    # live with a short select() wait so scheduled writer/reader work continues
    # while an operator leaves this screen open.
    drain_stdin()
    menu_refresh_seconds = 2.0
    while True:
        cfg = load_config()
        try:
            exotic_key_manager_tick(cfg)
        except Exception as exc:
            log_activity(f"Exotic key manager menu tick failed: {cut(exc, 90)}", "", YELLOW)
        state = load_exotic_key_state()
        clear()
        banner("EXOTIC KEY MANAGER", cfg)

        manager = bool(cfg.get("exotic_key_manager_enabled", True))
        reader = bool(cfg.get("exotic_key_reader_enabled", True))
        writer = bool(cfg.get("exotic_key_writer_enabled", False))
        worker = _exotic_worker_base(cfg)
        secret_set = bool(str(cfg.get("exotic_key_write_secret", "") or "").strip())
        secret_status = str(state.get("writer_secret_status") or "").strip().lower()
        verified_at = int(state.get("writer_secret_verified_at", 0) or 0)
        key = _exotic_clean_key(state.get("key"))

        with _EXOTIC_KEY_JOB_LOCK:
            job_running = bool(_EXOTIC_KEY_JOB.get("running"))
            job_mode = str(_EXOTIC_KEY_JOB.get("mode") or "").upper()

        ready_text, ready_color = _exotic_writer_readiness(cfg, state)
        role = "WRITER" if writer else "READER"

        print(col(f"ROLE:            {role}", YELLOW if writer else GREEN))
        print(f"Key manager:     {col('ON', GREEN) if manager else col('OFF', RED)}")
        reader_text = "ON"
        if not reader:
            reader_text = "OFF"
        elif writer:
            reader_text = "ON (standby while Writer is active)"
        print(f"Cloud reader:    {reader_text}")
        print(f"Writer mode:     {col('ON', GREEN) if writer else col('OFF', DIM)}")
        if writer:
            print("Auto writer:     " + col(ready_text, ready_color))
        print("")

        print(f"Worker URL:      {worker or '-'}")
        if not secret_set:
            secret_line = col("MISSING", RED)
        elif secret_status == "verified" and verified_at > 0:
            secret_line = col("SET + VERIFIED", GREEN) + f" ({_exotic_menu_time(verified_at)})"
        elif secret_status == "rejected":
            secret_line = col("SET BUT REJECTED", RED)
        else:
            secret_line = col("SET - not verified yet", YELLOW)
        print(f"Writer secret:   {secret_line}")
        print(f"Background job:  {job_mode if job_running else 'IDLE'}")
        print("")

        print(f"Local key:       {mask_secret(key) if key else '-'}")
        print(f"Key source:      {state.get('key_source', '-') or '-'}")
        print(f"Generated:       {_exotic_menu_time(state.get('generated_at'))}")
        print(f"Expires:         {_exotic_menu_time(state.get('expires_at'))}")
        print(f"Auto refresh:    {_exotic_menu_time(state.get('refresh_at'))} ({_exotic_menu_wait(state.get('refresh_at'))})")
        print(f"Cloud pending:   {'YES' if bool(state.get('cloud_pending', False)) else 'NO'}")
        if writer:
            print(f"Writer retry:    {_exotic_menu_wait(state.get('next_writer_retry_at'))}")
            print(f"Next verify:     {_exotic_menu_wait(state.get('next_writer_verify_at'))}")
        else:
            print(f"Next cloud read: {_exotic_menu_wait(state.get('next_cloud_check_at'))}")
        print(f"Last cloud OK:   {_exotic_menu_time(state.get('last_cloud_ok_at') or state.get('last_cloud_upload_at'))}")
        print(f"Cloud verify:    {state.get('writer_cloud_verify_status', '-') or '-'}")
        if state.get("writer_cloud_verify_note"):
            print(f"Verify note:     {cut(state.get('writer_cloud_verify_note', ''), 90)}")
        print(f"Last cloud err:  {cut(state.get('last_cloud_error', ''), 90) or '-'}")
        print(f"Last writer err: {cut(state.get('last_writer_error', ''), 90) or '-'}")
        print("")

        print(f"1. Key manager: {'ON' if manager else 'OFF'}  [toggle]")
        print(f"2. Cloud reader: {'ON' if reader else 'OFF'}  [toggle]")
        print(f"3. Writer mode: {'ON' if writer else 'OFF'}  [toggle THIS DEVICE]")
        print("4. Set Worker URL")
        print(f"5. Set writer secret ({'SET' if secret_set else 'MISSING'})")
        print("6. Set reader interval seconds")
        print("7. Test/sync Cloudflare READ now")
        print("8. Generate + publish NEW key now (writer only)")
        print("9. Import legacy key_cloudflare.json")
        print("10. Re-sync saved key to local UID files")
        print("0. Back")
        print(col("Live refresh: ~2s (Key Manager keeps running while this menu is open)", DIM))
        print("\nChoose: ", end="", flush=True)
        try:
            ready, _, _ = select.select([sys.stdin], [], [], menu_refresh_seconds)
        except Exception:
            # Fallback for an unusual TTY where select() is unavailable.
            ch = normalize_menu_choice(input())
        else:
            if not ready:
                # No completed input line yet: redraw from fresh state.
                continue
            raw_choice = sys.stdin.readline()
            ch = normalize_menu_choice(raw_choice)

        if ch == "0":
            return
        if ch == "1":
            new_value = not bool(cfg.get("exotic_key_manager_enabled", True))
            if not new_value and writer:
                print(col("Writer mode will remain configured but automatic generation/sync will be SUSPENDED.", YELLOW))
                if not _setup_yes_no("Turn the Exotic Key Manager OFF?", default=False):
                    continue
            cfg["exotic_key_manager_enabled"] = new_value
            save_config(cfg)
        elif ch == "2":
            cfg["exotic_key_reader_enabled"] = not bool(cfg.get("exotic_key_reader_enabled", True))
            save_config(cfg)
        elif ch == "3":
            enable = not bool(cfg.get("exotic_key_writer_enabled", False))
            if enable:
                print(col("Only ONE device may be the writer.", YELLOW))
                if not _setup_yes_no("Make this device the Exotic key writer?", default=False):
                    continue
                cfg["exotic_key_manager_enabled"] = True
            cfg["exotic_key_writer_enabled"] = enable
            save_config(cfg)
            print(col(
                "Writer ON; Key Manager automatically ON." if enable else "Writer OFF; this device will use reader mode when reader is enabled.",
                GREEN if enable else CYAN,
            ))
            time.sleep(1)
        elif ch == "4":
            raw = input(f"Worker URL [{cfg.get('exotic_key_worker_url')}]: ").strip()
            if raw:
                cfg["exotic_key_worker_url"] = raw.rstrip("/")
                save_config(cfg)
                state = load_exotic_key_state()
                state["writer_secret_status"] = "unverified"
                state["writer_secret_verified_at"] = 0
                save_exotic_key_state(state)
        elif ch == "5":
            secret = getpass.getpass("Exotic key Worker WRITE secret: ").strip()
            if secret:
                cfg["exotic_key_write_secret"] = secret
                save_config(cfg)
                state = load_exotic_key_state()
                state["writer_secret_status"] = "unverified"
                state["writer_secret_verified_at"] = 0
                save_exotic_key_state(state)
                print(col("Writer secret saved. It becomes VERIFIED after the first successful Cloudflare PUT.", GREEN))
                time.sleep(1.5)
        elif ch == "6":
            raw = input(f"Reader interval seconds [{cfg.get('exotic_key_sync_interval_seconds', 600)}]: ").strip()
            if raw.isdigit():
                cfg["exotic_key_sync_interval_seconds"] = max(300, int(raw))
                save_config(cfg)
        elif ch == "7":
            if not manager:
                print(col("BLOCKED: Key Manager is OFF. Toggle option 1 ON first.", RED))
                pause()
                continue
            result = exotic_key_manager_tick(cfg, force_read=True)
            labels = {
                "reader_started": "Cloudflare READ started in background",
                "reader_busy": "A key-manager background job is already running",
                "writer_started": "Writer generation started (writer role takes priority over reader)",
                "writer_verify_started": "Writer cloud-key verification READ started in background",
                "writer_conflict": "WRITER CONFLICT: cloud key differs; automatic writer actions are blocked",
                "writer_busy": "Writer background job already running",
                "writer_secret_missing": "BLOCKED: writer secret missing",
            }
            print(col(labels.get(result, f"Key sync result: {result}"), CYAN if "BLOCKED" not in labels.get(result, "") else RED))
            time.sleep(2)
        elif ch == "8":
            if not writer:
                print(col("BLOCKED: Writer mode is OFF on this device. Toggle option 3 first.", RED))
                pause()
                continue
            if not manager:
                print(col("BLOCKED: Key Manager is OFF. Toggle option 1 ON first.", RED))
                pause()
                continue
            if not worker.startswith("https://"):
                print(col("BLOCKED: Worker URL is missing/invalid. Set option 4 first.", RED))
                pause()
                continue
            if not secret_set:
                print(col("BLOCKED: Writer secret is missing. Set option 5 first.", RED))
                pause()
                continue
            result = exotic_key_manager_tick(cfg, force_generate=True)
            labels = {
                "writer_started": "NEW KEY generation started in background",
                "writer_busy": "Writer is already busy; no duplicate generation started",
                "writer_secret_missing": "BLOCKED: writer secret missing",
                "disabled": "BLOCKED: Key Manager is OFF",
            }
            text = labels.get(result, f"Writer result: {result}")
            print(col(text, RED if text.startswith("BLOCKED") else CYAN))
            print(col("This menu refreshes automatically; Generated/Cloud/Secret status will update here.", DIM))
            time.sleep(1)
        elif ch == "9":
            ok, note = exotic_key_import_legacy_config(cfg)
            print(col(note, GREEN if ok else YELLOW))
            if ok:
                print(col("Imported writer secret => Writer ON + Key Manager ON.", GREEN))
            pause()
        elif ch == "10":
            state = load_exotic_key_state()
            key = _exotic_clean_key(state.get("key"))
            if not key:
                print(col("No saved local Exotic key.", RED))
            else:
                ok, note, shared, uids = sync_exotic_key_to_local_workspaces(key, "manual")
                print(col(f"{note}; shared={shared} uid={uids}", GREEN if ok else RED))
            pause()



NOMO_AUTOEXEC_BACKUP_DIR = BASE_DIR / "autoexec_backups"
_NOMO_AUTOEXEC_LIVE_FILES = {
    "nomo_market_loader.lua",
    "nomo_pet_counter.lua",
    "nomo_booster_probe.lua",
}


def _nomo_autoexec_external_backup_path(path, tag="backup"):
    """Return a unique NOMO backup path that is never inside an AutoExec folder."""
    path = Path(path)
    NOMO_AUTOEXEC_BACKUP_DIR.mkdir(parents=True, exist_ok=True)
    safe_tag = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(tag or "backup"))[:48] or "backup"
    stamp = f"{int(time.time())}.{os.getpid()}.{time.time_ns() % 1000000000}"
    return NOMO_AUTOEXEC_BACKUP_DIR / f"{path.name}.{safe_tag}.{stamp}.bak"


def _backup_nomo_autoexec_outside(path, tag="backup"):
    """Copy one live NOMO AutoExec file to NOMO storage, never beside executable files."""
    path = Path(path)
    if not path.exists() or not path.is_file():
        return None
    target = _nomo_autoexec_external_backup_path(path, tag)
    shutil.copy2(path, target)
    return target


def _write_nomo_autoexec_text(path, content, *, backup_tag=None):
    """Write AutoExec content without ever creating a temp/backup beside executable files."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    if backup_tag and path.exists():
        _backup_nomo_autoexec_outside(path, backup_tag)
    staging = _nomo_autoexec_external_backup_path(path, "staging")
    staging.write_text(str(content), encoding="utf-8")
    try:
        os.replace(str(staging), str(path))
    except Exception:
        shutil.copy2(staging, path)
        try:
            staging.unlink()
        except Exception:
            pass
    return path


def _is_nomo_autoexec_backup_artifact(path):
    """Match only NOMO-owned stale backup/temp artifacts, never arbitrary user files."""
    name = Path(path).name.lower()
    for live in _NOMO_AUTOEXEC_LIVE_FILES:
        live = live.lower()
        if not name.startswith(live + "."):
            continue
        tail = name[len(live) + 1:]
        if (
            ".bak" in tail
            or tail.endswith("bak")
            or ".tmp" in tail
            or tail.endswith("tmp")
            or "disabled_" in tail
        ):
            return True
    return False


def cleanup_nomo_autoexec_backup_artifacts(cfg):
    """Move old NOMO backup/temp files out of AutoExec so Delta cannot execute them."""
    moved = 0
    errors = []
    seen_folders = set()
    for tab in autoexec_tabs(cfg):
        # Resolve the same live Market loader location used by automatic migration.
        for live_name in sorted(_NOMO_AUTOEXEC_LIVE_FILES):
            try:
                paths = autoexec_paths_for_tab(tab, "1", filename=live_name)
            except Exception:
                paths = []
            for live_path in paths:
                folder = Path(live_path).parent
                key = str(folder)
                if key in seen_folders:
                    continue
                seen_folders.add(key)
                try:
                    entries = list(folder.iterdir()) if folder.exists() else []
                except Exception as exc:
                    errors.append(f"{folder}: {exc}")
                    continue
                for item in entries:
                    try:
                        if not item.is_file() or not _is_nomo_autoexec_backup_artifact(item):
                            continue
                        target = _nomo_autoexec_external_backup_path(item, "autoexec-cleanup")
                        try:
                            shutil.move(str(item), str(target))
                        except Exception:
                            shutil.copy2(item, target)
                            item.unlink()
                        moved += 1
                    except Exception as exc:
                        errors.append(f"{item}: {exc}")
    return moved, errors

def upgrade_known_nomo_market_loader_once(cfg):
    """Upgrade only known NOMO loader generations; preserve unrelated/custom AutoExec."""
    marker = "-- NOMO Market / GAG loader"
    target_revision = 8
    target_marker = f"-- NOMO Market loader revision {target_revision}"
    old_worker = "https://nomo-key.atmincosplay.workers.dev/key"
    local_key_marker = 'local sharedKeyFile = sharedFolder .. "/exotic_key.json"'
    market_remote_marker = 'atmincosplay-ship-it/nomo-market/main/nomo_obsidian.lua'
    runtime_marker_v1 = "-- NOMO Market runtime marker v1"
    changed = 0
    seen = set()
    for tab in autoexec_tabs(cfg):
        for path in autoexec_paths_for_tab(tab, "1", filename=AUTOEXEC_MARKET_LOADER_FILE):
            if str(path) in seen:
                continue
            seen.add(str(path))
            try:
                if not path.exists():
                    continue
                old = path.read_text(encoding="utf-8", errors="ignore")
                if marker not in old:
                    continue
                rev_match = re.search(r"-- NOMO Market loader revision (\d+)", old)
                old_revision = int(rev_match.group(1)) if rev_match else 0
                if old_revision >= target_revision and target_marker in old:
                    continue
                known_old = old_worker in old
                known_v481 = local_key_marker in old and market_remote_marker in old
                known_runtime = runtime_marker_v1 in old
                if not (known_old or known_v481 or known_runtime or old_revision > 0):
                    continue
                # Never leave backup/temp scripts in AutoExec: some executors may execute
                # every file in this folder regardless of extension.
                _write_nomo_autoexec_text(
                    path,
                    MARKET_LOADER_AUTOEXEC_TEMPLATE,
                    backup_tag=f"pre-loader-rev{target_revision}",
                )
                changed += 1
            except Exception:
                continue
    return changed


def upgrade_known_nomo_aux_loaders_once(cfg):
    """Upgrade known NOMO Pet Counter / Booster loaders in-place.

    Existing global Arceus AutoExec files do not automatically change when the
    Python generator changes. Keep this narrow to exact NOMO filenames+markers
    and use the external-backup writer so AutoExec never accumulates .bak files.
    """
    specs = [
        (
            AUTOEXEC_PET_COUNTER_FILE,
            "-- NOMO Pet Counter updater/loader",
            r"-- NOMO Pet Counter loader revision (\d+)",
            2,
            pet_counter_autoexec_source,
            "pet-counter",
        ),
        (
            AUTOEXEC_BOOSTER_PROBE_FILE,
            "-- NOMO Booster scanner updater/loader",
            r"-- NOMO Booster loader revision (\d+)",
            2,
            booster_probe_autoexec_source,
            "booster",
        ),
    ]
    changed = 0
    seen = set()
    for tab in autoexec_tabs(cfg):
        for filename, marker_text, rev_pattern, target_revision, source_fn, tag in specs:
            for path in autoexec_paths_for_tab(tab, "1", filename=filename):
                key = str(path)
                if key in seen:
                    continue
                seen.add(key)
                try:
                    if not path.exists():
                        continue
                    old = path.read_text(encoding="utf-8", errors="ignore")
                    if marker_text not in old:
                        continue
                    match = re.search(rev_pattern, old)
                    old_revision = int(match.group(1)) if match else 0
                    if old_revision >= target_revision:
                        continue
                    _write_nomo_autoexec_text(
                        path,
                        source_fn(),
                        backup_tag=f"pre-{tag}-rev{target_revision}",
                    )
                    changed += 1
                except Exception:
                    continue
    return changed


MARKET_LOADER_AUTOEXEC_TEMPLATE = r'''-- NOMO Market / GAG loader
-- NOMO Market loader revision 8
if not game:IsLoaded() then
    game.Loaded:Wait()
end

if game.PlaceId == 126884695634066 then
    -- Grow a Garden / Hatcher
    print("grow a garden")
    local Players = game:GetService("Players")
    local HttpService = game:GetService("HttpService")

    local player = Players.LocalPlayer or Players.PlayerAdded:Wait()
    local userId = tostring(player.UserId)
    local loginFile = userId .. "_exologin.json"
    local sharedFolder = "Nomo"
    local sharedKeyFile = sharedFolder .. "/exotic_key.json"
    local statusFile = sharedFolder .. "/exotic_status_" .. userId .. ".json"
    local exoticCacheFile = sharedFolder .. "/exotic_last_good_" .. userId .. ".lua"
    local keySource = ""
    local scriptSource = "none"

    local function clean(value)
        if type(value) ~= "string" then
            return nil
        end
        value = value:match("^%s*(.-)%s*$")
        if value == "" or value == "KEY_NOT_AVAILABLE" then
            return nil
        end
        return value
    end

    local function ensureFolder(folder)
        pcall(function()
            if type(isfolder) == "function" then
                if not isfolder(folder) and type(makefolder) == "function" then
                    makefolder(folder)
                end
            elseif type(makefolder) == "function" then
                makefolder(folder)
            end
        end)
    end

    local function epochNow()
        local ok, value = pcall(function()
            return DateTime.now().UnixTimestamp
        end)
        if ok and type(value) == "number" then
            return math.floor(value)
        end
        local ok2, value2 = pcall(os.time)
        if ok2 and type(value2) == "number" then
            return math.floor(value2)
        end
        return 0
    end

    local function writeStatus(stage, err)
        if type(writefile) ~= "function" then
            return
        end
        ensureFolder(sharedFolder)
        local payload = {
            uid = userId,
            username = player.Name,
            display_name = player.DisplayName,
            place_id = tostring(game.PlaceId or ""),
            job_id = tostring(game.JobId or ""),
            ts = epochNow(),
            stage = tostring(stage or "UNKNOWN"),
            ok = stage == "EXOTIC_STARTED",
            key_source = keySource,
            exotic_source = scriptSource,
            exotic_cache_file = exoticCacheFile,
            exotic_cache_available = (type(isfile) == "function" and isfile(exoticCacheFile)) or false,
            loader_build = "V4.81.52",
            loader_revision = 8,
            error = tostring(err or ""),
        }
        pcall(function()
            writefile(statusFile, HttpService:JSONEncode(payload))
        end)
    end

    local function saveLoginFile(key)
        if type(writefile) ~= "function" then
            return false
        end
        local data = {
            token = key,
            type = "lootlabs"
        }
        local ok = pcall(function()
            writefile(loginFile, HttpService:JSONEncode(data))
        end)
        return ok
    end

    local function readJsonToken(path)
        if type(isfile) ~= "function" or type(readfile) ~= "function" then
            return nil
        end
        if not isfile(path) then
            return nil
        end
        local ok, content = pcall(readfile, path)
        if not ok then
            return nil
        end
        local decodedOk, data = pcall(function()
            return HttpService:JSONDecode(content)
        end)
        if decodedOk and type(data) == "table" then
            return clean(data.token or data.key)
        end
        return nil
    end

    writeStatus("LOADER_STARTED", "")

    -- Device-shared key is authoritative because NOMO Termux updates it first.
    -- If a per-UID file missed a sync/write, repair it before Exotic starts.
    local uidKey = readJsonToken(loginFile)
    local sharedKey = readJsonToken(sharedKeyFile)
    local key = nil

    if sharedKey then
        key = sharedKey
        if uidKey and uidKey ~= sharedKey then
            keySource = "device_shared_repair"
            saveLoginFile(sharedKey)
        elseif uidKey then
            keySource = "uid_matches_device_shared"
        else
            keySource = "device_shared_local"
            saveLoginFile(sharedKey)
        end
    elseif uidKey then
        key = uidKey
        keySource = "uid_exologin_fallback"
    end

    if not key then
        writeStatus("KEY_MISSING", "No local UID or shared Exotic key")
        warn("[NOMO EXOTIC] local key missing; NOMO Termux key sync is required")
        return
    end

    getgenv().exo_key = key
    writeStatus("KEY_READY", "")
    task.wait(5)

    local function compileExoticSource(text)
        if type(text) ~= "string" or #text < 20 then
            return nil, "source missing/too small"
        end
        local chunk, compileErr = loadstring(text)
        if type(chunk) ~= "function" then
            return nil, tostring(compileErr)
        end
        return chunk, ""
    end

    local function readExoticCache()
        if type(readfile) ~= "function" then
            return nil
        end
        local ok, text = pcall(function()
            if type(isfile) == "function" and not isfile(exoticCacheFile) then
                return nil
            end
            return readfile(exoticCacheFile)
        end)
        if not ok then
            return nil
        end
        local chunk = compileExoticSource(text)
        if type(chunk) == "function" then
            return text
        end
        return nil
    end

    local function saveExoticCache(text)
        if type(writefile) ~= "function" then
            return false
        end
        local chunk = compileExoticSource(text)
        if type(chunk) ~= "function" then
            return false
        end
        ensureFolder(sharedFolder)
        return pcall(function()
            writefile(exoticCacheFile, text)
        end)
    end

    local selectedSource = nil
    local selectedChunk = nil
    local sourceErr = ""
    local downloadOk, remoteText = pcall(function()
        return game:HttpGet("https://exotichub.app/auto.lua", true)
    end)
    if downloadOk then
        local remoteChunk, remoteCompileErr = compileExoticSource(remoteText)
        if type(remoteChunk) == "function" then
            selectedSource = remoteText
            selectedChunk = remoteChunk
            scriptSource = "remote"
            writeStatus("EXOTIC_DOWNLOADED", "")
        else
            sourceErr = "remote compile/validation failed: " .. tostring(remoteCompileErr)
        end
    else
        sourceErr = "remote download failed: " .. tostring(remoteText)
    end

    if not selectedChunk then
        local cachedText = readExoticCache()
        if cachedText then
            local cachedChunk, cachedCompileErr = compileExoticSource(cachedText)
            if type(cachedChunk) == "function" then
                selectedSource = cachedText
                selectedChunk = cachedChunk
                scriptSource = "cache"
                writeStatus("EXOTIC_CACHE_READY", sourceErr)
                warn("[NOMO EXOTIC] remote unavailable/bad; using last-good cache:", sourceErr)
            else
                sourceErr = sourceErr .. " | cache compile failed: " .. tostring(cachedCompileErr)
            end
        else
            sourceErr = sourceErr .. " | no valid last-good cache"
        end
    end

    if type(selectedChunk) ~= "function" then
        writeStatus("EXOTIC_SOURCE_UNAVAILABLE", sourceErr)
        warn("[NOMO EXOTIC] no usable source:", sourceErr)
        return
    end

    writeStatus("EXOTIC_EXECUTING", "")
    local runOk, runErr = pcall(selectedChunk)
    if not runOk then
        writeStatus("EXOTIC_RUNTIME_FAILED", tostring(runErr))
        warn("[NOMO EXOTIC] " .. tostring(scriptSource) .. " runtime failed:", tostring(runErr))
        return
    end

    -- A remote source can replace last-good only after successful execution.
    if scriptSource == "remote" then
        if not saveExoticCache(selectedSource) then
            warn("[NOMO EXOTIC] remote started OK, but last-good cache write failed")
        end
    end
    writeStatus("EXOTIC_STARTED", "")

    pcall(function()
        game:GetService("RunService"):Set3dRenderingEnabled(true)
    end)

    pcall(function()
        if setfpscap then
            setfpscap(5)
        end
    end)

    pcall(function()
        local s = settings()
        s.Rendering.QualityLevel = Enum.QualityLevel.Level01
        s.Physics.PhysicsEnvironmentalThrottle = Enum.EnviromentalPhysicsThrottle.Always
        s.Physics.AllowSleep = true
    end)

    pcall(function()
        local userSettings = UserSettings():GetService("UserGameSettings")
        userSettings.MasterVolume = 0
    end)

elseif game.PlaceId == 129954712878723 then
    -- Trade World / Market
    -- NOMO Market runtime marker v5
    print("trade world")

    local Players = game:GetService("Players")
    local HttpService = game:GetService("HttpService")
    local player = Players.LocalPlayer or Players.PlayerAdded:Wait()
    local userId = tostring(player.UserId)
    local runtimeFolder = "Nomo"
    local runtimeFile = runtimeFolder .. "/market_runtime_" .. userId .. ".json"
    local marketUrl = "https://raw.githubusercontent.com/atmincosplay-ship-it/nomo-market/main/nomo_obsidian.lua"
    local marketMirrorUrl = "https://cdn.jsdelivr.net/gh/atmincosplay-ship-it/nomo-market@main/nomo_obsidian.lua"
    local marketCandidateFile = runtimeFolder .. "/market_candidate.lua"
    local marketCacheFile = runtimeFolder .. "/market_last_good_" .. userId .. ".lua"
    local legacyMarketCacheFile = runtimeFolder .. "/market_last_good.lua"
    local loaderStartedAt = 0
    local marketVersion = "UNKNOWN"
    local marketSourceName = "none"
    local marketRemoteError = ""

    local function epochNow()
        local ok, value = pcall(function()
            return DateTime.now().UnixTimestamp
        end)
        if ok and type(value) == "number" then
            return math.floor(value)
        end
        local ok2, value2 = pcall(os.time)
        if ok2 and type(value2) == "number" then
            return math.floor(value2)
        end
        return 0
    end

    loaderStartedAt = epochNow()

    local function ensureRuntimeFolder()
        pcall(function()
            if type(isfolder) == "function" then
                if not isfolder(runtimeFolder) and type(makefolder) == "function" then
                    makefolder(runtimeFolder)
                end
            elseif type(makefolder) == "function" then
                makefolder(runtimeFolder)
            end
        end)
    end

    local function marketState()
        local ok, value = pcall(function()
            return getgenv().__NOMO_MARKET_V30_STATE
        end)
        if ok and type(value) == "table" then
            return value
        end
        return nil
    end

    local function marketCfg()
        local ok, value = pcall(function()
            return getgenv().NOMO_MARKET
        end)
        if ok and type(value) == "table" then
            return value
        end
        return nil
    end

    local function snapshot(stage, err)
        local state = marketState()
        local cfg = marketCfg()
        local seller = cfg and cfg.Seller or nil
        local refreshSeconds = tonumber(seller and seller.RemoteConfigRefreshSeconds) or 21600
        local lastFetch = tonumber(state and state.LastRemoteConfigUnix) or 0
        local nextFetch = 0
        if lastFetch > 0 then
            nextFetch = lastFetch + refreshSeconds
        elseif loaderStartedAt > 0 then
            nextFetch = loaderStartedAt + refreshSeconds
        end
        local backoffUntil = tonumber(state and state.RemoteConfigBackoffUntil) or 0
        local source = tostring(state and state.SharedConfigSource or "")
        return {
            marker_version = 5,
            loader_version = "V4.81.52",
            loader_build = "V4.81.52",
            loader_revision = 8,
            market_version = tostring(marketVersion or "UNKNOWN"),
            market_source = tostring(marketSourceName or "none"),
            market_remote_error = tostring(marketRemoteError or ""),
            market_candidate_file = marketCandidateFile,
            market_candidate_available = (type(isfile) == "function" and isfile(marketCandidateFile)) or false,
            market_cache_file = marketCacheFile,
            market_cache_available = (type(isfile) == "function" and isfile(marketCacheFile)) or false,
            uid = userId,
            username = tostring(player.Name or ""),
            display_name = tostring(player.DisplayName or ""),
            place_id = tostring(game.PlaceId or ""),
            job_id = tostring(game.JobId or ""),
            loader_started_at = loaderStartedAt,
            updated_at = epochNow(),
            stage = tostring(stage or "UNKNOWN"),
            ok = stage == "MARKET_RUNNING",
            market_running = state ~= nil and state.Running ~= false,
            remote_config_enabled = seller == nil or seller.RemoteConfigEnabled ~= false,
            remote_config_refresh_seconds = refreshSeconds,
            remote_config_last_fetch = lastFetch,
            remote_config_next_fetch = nextFetch,
            remote_config_backoff_until = backoffUntil,
            remote_config_source = source,
            remote_config_applied = state ~= nil and state.RemoteConfigApplied == true,
            error = tostring(err or ""),
        }
    end

    local function writeRuntime(stage, err)
        if type(writefile) ~= "function" then
            return false
        end
        ensureRuntimeFolder()
        local payload = snapshot(stage, err)
        local ok, encoded = pcall(function()
            return HttpService:JSONEncode(payload)
        end)
        if not ok then
            return false
        end
        return pcall(function()
            writefile(runtimeFile, encoded)
        end)
    end

    local function marketVersionParts(text)
        if type(text) ~= "string" then
            return nil, nil, nil
        end
        local full = text:match('local%s+VERSION%s*=%s*"(V[^"]+)"')
        if not full then
            return nil, nil, nil
        end
        local major, minor = full:match('^V(%d+)%.(%d+)')
        return tonumber(major), tonumber(minor), full
    end

    local function marketVersionAtLeast(text, minMajor, minMinor)
        local major, minor = marketVersionParts(text)
        if not major or not minor then
            return false
        end
        if major ~= minMajor then
            return major > minMajor
        end
        return minor >= minMinor
    end

    local function validMarketSource(text)
        if type(text) ~= "string" or #text < 20000 then
            return false
        end
        return string.find(text, "NOMO MARKET SELLER LITE", 1, true) ~= nil
            and string.find(text, "__NOMO_MARKET_V30_STATE", 1, true) ~= nil
            and string.find(text, "RemoteConfigRefreshSeconds", 1, true) ~= nil
            and marketVersionAtLeast(text, 17, 5)
    end

    local function readOneMarketCache(path)
        if type(readfile) ~= "function" then
            return nil
        end
        local ok, text = pcall(function()
            if type(isfile) == "function" and not isfile(path) then
                return nil
            end
            return readfile(path)
        end)
        if ok and validMarketSource(text) then
            return text
        end
        return nil
    end

    local function readMarketCache()
        local text = readOneMarketCache(marketCacheFile)
        if text then
            return text
        end
        -- One-time compatibility migration from V4.81.10's device-shared cache.
        local legacy = readOneMarketCache(legacyMarketCacheFile)
        if legacy then
            ensureRuntimeFolder()
            if type(writefile) == "function" then
                pcall(function()
                    writefile(marketCacheFile, legacy)
                end)
            end
            return legacy
        end
        return nil
    end

    local function readMarketCandidate()
        return readOneMarketCache(marketCandidateFile)
    end

    local function deleteMarketCandidate()
        if type(delfile) ~= "function" then
            return
        end
        pcall(function()
            if type(isfile) ~= "function" or isfile(marketCandidateFile) then
                delfile(marketCandidateFile)
            end
        end)
    end

    local function saveMarketCache(text)
        if type(writefile) ~= "function" or not validMarketSource(text) then
            return false
        end
        ensureRuntimeFolder()
        return pcall(function()
            writefile(marketCacheFile, text)
        end)
    end

    writeRuntime("LOADER_STARTED", "")

    local marketSource = nil
    local marketChunk = nil
    local sourceErr = ""

    local function tryMarketText(text, sourceName, failurePrefix)
        if not validMarketSource(text) then
            return false, tostring(failurePrefix or sourceName) .. " source validation failed or version older than V17.5"
        end
        local chunk, compileErr = loadstring(text)
        if type(chunk) ~= "function" then
            return false, tostring(failurePrefix or sourceName) .. " compile failed: " .. tostring(compileErr)
        end
        marketSource = text
        marketChunk = chunk
        marketSourceName = sourceName
        return true, ""
    end

    local function tryMarketUrl(url, sourceName)
        local ok, body = pcall(function()
            return game:HttpGet(url, true)
        end)
        if not ok then
            return false, sourceName .. " download failed: " .. tostring(body)
        end
        return tryMarketText(body, sourceName, sourceName)
    end

    -- Prefer direct GitHub. If raw.githubusercontent.com is blocked for the
    -- executor, prefer the Termux-staged candidate next: it was downloaded and
    -- validated outside Roblox and may be newer than a CDN's branch cache.
    local okGithub, errGithub = tryMarketUrl(marketUrl, "github")
    if not okGithub then
        sourceErr = errGithub
    end

    if not marketSource then
        local candidateText = readMarketCandidate()
        if candidateText then
            local okCandidate, errCandidate = tryMarketText(candidateText, "candidate", "candidate")
            if not okCandidate then
                sourceErr = sourceErr .. " | " .. errCandidate
            end
        else
            sourceErr = sourceErr .. " | no valid staged candidate"
        end
    end

    if not marketSource then
        local okMirror, errMirror = tryMarketUrl(marketMirrorUrl, "jsdelivr")
        if not okMirror then
            sourceErr = sourceErr .. " | " .. errMirror
        end
    end

    if not marketSource then
        local cachedText = readMarketCache()
        if cachedText then
            local okCache, errCache = tryMarketText(cachedText, "cache", "cache")
            if not okCache then
                sourceErr = sourceErr .. " | " .. errCache
            else
                warn("[NOMO MARKET] live sources unavailable/bad; using last-good cache:", tostring(sourceErr))
            end
        else
            sourceErr = sourceErr .. " | no valid last-good cache"
        end
    end

    marketRemoteError = sourceErr
    if not marketSource or type(marketChunk) ~= "function" then
        writeRuntime("SOURCE_UNAVAILABLE", sourceErr)
        warn("[NOMO MARKET] no usable Market source:", sourceErr)
        return
    end

    marketVersion = marketSource:match('local%s+VERSION%s*=%s*"([^"]+)"') or "UNKNOWN"
    writeRuntime("SOURCE_READY", "")

    -- V4.81.52: bounded in-place runtime self-heal. A transient dependency
    -- failure must not require an Android reopen just to rerun this AutoExec
    -- chunk. Never retry forever: three attempts, 30 seconds apart.
    local runtimeRetryLimit = 3
    local runtimeRetrySeconds = 30
    local runOk = false
    local runErr = ""
    for attempt = 1, runtimeRetryLimit do
        runOk, runErr = pcall(marketChunk)
        if runOk then
            break
        end

        -- If the source raised after it had already brought Market up, trust
        -- the live state and do not execute a duplicate copy on top of it.
        local partialState = marketState()
        if partialState ~= nil and partialState.Running ~= false then
            runOk = true
            runErr = ""
            break
        end

        writeRuntime(
            "RUNTIME_FAILED",
            "attempt " .. tostring(attempt) .. "/" .. tostring(runtimeRetryLimit)
                .. ": " .. tostring(runErr)
        )
        warn(
            "[NOMO MARKET] " .. tostring(marketSourceName)
                .. " runtime failed attempt " .. tostring(attempt)
                .. "/" .. tostring(runtimeRetryLimit) .. ":",
            tostring(runErr)
        )
        if attempt < runtimeRetryLimit then
            task.wait(runtimeRetrySeconds)
        end
    end
    if not runOk then
        return
    end

    -- Only a source that actually started successfully may replace last-good.
    -- A bad HTTP response, candidate, compile, or runtime can never poison it.
    if marketSourceName == "github" or marketSourceName == "jsdelivr" or marketSourceName == "candidate" then
        local cacheOk = saveMarketCache(marketSource)
        if not cacheOk then
            warn("[NOMO MARKET] running source OK, but last-good cache write failed:", tostring(marketSourceName))
        elseif marketSourceName == "candidate" then
            deleteMarketCandidate()
        end
    end

    writeRuntime("MARKET_RUNNING", "")

    -- Update on interesting state changes, plus a 60-second LOCAL heartbeat.
    -- V4.81.52: this lets a stale/forced failure marker self-correct quickly
    -- when Market is actually still running. This performs NO HTTP/Worker requests.
    task.spawn(function()
        local lastSignature = ""
        local lastWriteAt = 0
        while true do
            local state = marketState()
            local cfg = marketCfg()
            local seller = cfg and cfg.Seller or nil
            local refreshSeconds = tonumber(seller and seller.RemoteConfigRefreshSeconds) or 21600
            local lastFetch = tonumber(state and state.LastRemoteConfigUnix) or 0
            local backoffUntil = tonumber(state and state.RemoteConfigBackoffUntil) or 0
            local source = tostring(state and state.SharedConfigSource or "")
            local applied = state ~= nil and state.RemoteConfigApplied == true
            local running = state ~= nil and state.Running ~= false
            local signature = table.concat({
                tostring(marketVersion),
                tostring(marketSourceName),
                tostring(refreshSeconds),
                tostring(lastFetch),
                tostring(backoffUntil),
                source,
                tostring(applied),
                tostring(running),
                tostring(game.JobId or ""),
            }, "|")
            local nowTs = epochNow()
            if signature ~= lastSignature or lastWriteAt <= 0 or (nowTs - lastWriteAt) >= 60 then
                writeRuntime(running and "MARKET_RUNNING" or "MARKET_STOPPED", "")
                lastSignature = signature
                lastWriteAt = nowTs
            end
            if state ~= nil and state.Running == false then
                break
            end
            task.wait(30)
        end
    end)

else
    print("unsupported place:", game.PlaceId)
    return
end
'''

BUNDLED_PET_COUNTER_FILE = BASE_DIR / "nomo_pet_counter.lua"


def _lua_long_string(text):
    """Return a Lua long-bracket string using a delimiter absent from text."""
    raw = str(text or "")
    for level in range(0, 20):
        eq = "=" * level
        closer = "]" + eq + "]"
        if closer not in raw:
            return "[" + eq + "[" + raw + "]" + eq + "]"
    raise ValueError("unable to create safe Lua long string")


def pet_counter_autoexec_source():
    """Build remote -> per-UID last-good -> embedded AutoExec loader.

    V4.81.20 only promotes a remote counter to cache after it compiles and its
    startup chunk returns successfully. Global Arceus workspaces therefore no
    longer make four accounts race on one shared cache file.
    """
    remote_url = json.dumps(NOMO_PET_COUNTER_URL)
    embedded = _lua_long_string(PET_COUNTER_FALLBACK_TEMPLATE)

    return f'''-- NOMO Pet Counter updater/loader
-- NOMO Pet Counter loader revision 2
-- Priority: GitHub latest -> per-UID last-good -> legacy cache -> embedded stable v3.9

local Players = game:GetService(\"Players\")
local LocalPlayer = Players.LocalPlayer or Players.PlayerAdded:Wait()
local COUNTER_URL = {remote_url}
local CACHE_FOLDER = \"nomo_rejoiner\"
local CACHE_FILE = CACHE_FOLDER .. \"/nomo_pet_counter_cache_\" .. tostring(LocalPlayer.UserId or \"unknown\") .. \".lua\"
local LEGACY_CACHE_FILE = CACHE_FOLDER .. \"/nomo_pet_counter_cache.lua\"
local EMBEDDED_FALLBACK = {embedded}

local function validCounterSource(text)
    return type(text) == \"string\"
        and #text > 1000
        and string.find(text, \"NOMO PET COUNTER\", 1, true) ~= nil
        and string.find(text, \"NOMO_PET_COUNTER\", 1, true) ~= nil
end

local function ensureCacheFolder()
    if type(makefolder) ~= \"function\" then return end
    pcall(function()
        if type(isfolder) == \"function\" then
            if not isfolder(CACHE_FOLDER) then makefolder(CACHE_FOLDER) end
        else
            makefolder(CACHE_FOLDER)
        end
    end)
end

local function saveCache(text)
    if type(writefile) ~= \"function\" or not validCounterSource(text) then return false end
    ensureCacheFolder()
    local ok = pcall(function() writefile(CACHE_FILE, text) end)
    return ok
end

local function readCachePath(path)
    if type(readfile) ~= \"function\" then return nil end
    local ok, text = pcall(function()
        if type(isfile) == \"function\" and not isfile(path) then return nil end
        return readfile(path)
    end)
    if ok and validCounterSource(text) then return text end
    return nil
end

local function runSource(text, name)
    if not validCounterSource(text) then
        return false, \"source validation failed\"
    end
    local chunk, compileError = loadstring(text)
    if not chunk then
        return false, \"compile failed: \" .. tostring(compileError)
    end
    print(\"[NOMO COUNTER LOADER] source = \" .. tostring(name))
    local runOk, runError = pcall(chunk)
    if not runOk then
        return false, \"runtime failed: \" .. tostring(runError)
    end
    return true, \"ok\"
end

local remoteOk, remoteText = pcall(function()
    return game:HttpGet(COUNTER_URL, true)
end)
if remoteOk and validCounterSource(remoteText) then
    local ok, err = runSource(remoteText, \"github\")
    if ok then
        saveCache(remoteText)
        return
    end
    warn(\"[NOMO COUNTER LOADER] remote rejected; keeping last-good:\", tostring(err))
end

local cached = readCachePath(CACHE_FILE)
if cached then
    local ok, err = runSource(cached, \"cache\")
    if ok then return end
    warn(\"[NOMO COUNTER LOADER] per-UID cache failed:\", tostring(err))
end

local legacy = readCachePath(LEGACY_CACHE_FILE)
if legacy then
    local ok, err = runSource(legacy, \"legacy-cache\")
    if ok then
        saveCache(legacy)
        return
    end
    warn(\"[NOMO COUNTER LOADER] legacy cache failed:\", tostring(err))
end

local ok, err = runSource(EMBEDDED_FALLBACK, \"embedded-v3.9\")
if not ok then
    warn(\"[NOMO COUNTER LOADER] embedded fallback failed:\", tostring(err))
end
'''


BOOSTER_PROBE_FALLBACK_TEMPLATE = '--========================================================--\n--                  NOMO BOOSTER PROBE\n--             v0.1.1 PETDATA CONTAINER FIX\n--========================================================--\n-- PURPOSE:\n--   Validate the real Grow a Garden pet schema before Booster mode is merged\n--   into NOMO REJOIN or the stable v3.9 pet counter.\n--\n-- SAFETY:\n--   - Does not teleport or rejoin.\n--   - Does not call Cloudflare or any web endpoint.\n--   - Does not modify <username>_state.json.\n--   - Does not stop/replace NOMO PET COUNTER.\n--   - Reads DataService once every 10 seconds by default.\n--\n-- OUTPUT:\n--   nomo_rejoiner/<username>_booster_probe.json\n--\n-- VALUABLE RULE:\n--   age >= 500\n--   OR\n--   truncated age-1 base weight >= 6.00 kg\n--\n-- AGE-1 BASE WEIGHT:\n--   BaseWeight is treated as age-0.\n--   age1 = BaseWeight * 1.1\n--   displayed/compared after truncating to two decimals, never rounding up.\n--========================================================--\n\nlocal Players = game:GetService("Players")\nlocal HttpService = game:GetService("HttpService")\nlocal ReplicatedStorage = game:GetService("ReplicatedStorage")\n\nlocal LocalPlayer = Players.LocalPlayer or Players.PlayerAdded:Wait()\n\n-- Stop only an older Booster probe. The normal NOMO counter is untouched.\ndo\n    local old = getgenv().NOMO_BOOSTER_PROBE\n    if type(old) == "table" then\n        old.Enabled = false\n        old.Stop = true\n    end\n    task.wait(0.25)\nend\n\ngetgenv().NOMO_BOOSTER_PROBE = getgenv().NOMO_BOOSTER_PROBE or {}\nlocal Config = getgenv().NOMO_BOOSTER_PROBE\n\nConfig.Enabled = true\nConfig.Stop = false\nConfig.Version = "v0.1-phase1-safe"\nConfig.Revision = "v0.1.1-petdata-container-fix"\n\nConfig.WriteFolder = Config.WriteFolder or "nomo_rejoiner"\nConfig.ScanEvery = math.max(5, tonumber(Config.ScanEvery or 10) or 10)\nConfig.MinAge = math.max(0, tonumber(Config.MinAge or 500) or 500)\nConfig.MinAge1BaseWeightKg = math.max(\n    0,\n    tonumber(Config.MinAge1BaseWeightKg or 6.00) or 6.00\n)\nConfig.MaxValuablePets = math.max(\n    1,\n    math.floor(tonumber(Config.MaxValuablePets or 250) or 250)\n)\nConfig.MaxSamplePets = math.max(\n    1,\n    math.floor(tonumber(Config.MaxSamplePets or 12) or 12)\n)\nConfig.MaxObservedKeys = math.max(\n    10,\n    math.floor(tonumber(Config.MaxObservedKeys or 100) or 100)\n)\nConfig.ExpectedPlaceId = tonumber(\n    Config.ExpectedPlaceId or 126884695634066\n) or 126884695634066\nConfig.OnlyScanExpectedPlace = Config.OnlyScanExpectedPlace ~= false\nConfig.Debug = Config.Debug == true\n\n-- Optional username allow-list:\n--   getgenv().NOMO_BOOSTER_PROBE.AllowedUsernames = {\n--       ["nomoboost1"] = true,\n--   }\n-- Empty/nil means all usernames on the test device.\nif type(Config.AllowedUsernames) ~= "table" then\n    Config.AllowedUsernames = {}\nend\n\nlocal function sanitizeName(value)\n    value = tostring(value or "")\n    value = string.gsub(value, "[^%w_]", "_")\n    if value == "" then\n        value = "unknown"\n    end\n    return value\nend\n\nlocal safeUser = sanitizeName(LocalPlayer.Name)\nConfig.WriteFile = Config.WriteFile\n    or (Config.WriteFolder .. "/" .. safeUser .. "_booster_probe.json")\n\nlocal function usernameAllowed()\n    if next(Config.AllowedUsernames) == nil then\n        return true\n    end\n    return Config.AllowedUsernames[LocalPlayer.Name] == true\nend\n\nlocal function safeMakeFolder(folder)\n    if type(writefile) ~= "function" then\n        return false, "writefile unavailable"\n    end\n\n    pcall(function()\n        if type(isfolder) == "function" then\n            if not isfolder(folder) and type(makefolder) == "function" then\n                makefolder(folder)\n            end\n        elseif type(makefolder) == "function" then\n            makefolder(folder)\n        end\n    end)\n\n    return true\nend\n\nlocal function safeWrite(path, text)\n    if type(writefile) ~= "function" then\n        return false, "writefile unavailable"\n    end\n\n    local tmp = path .. ".tmp"\n    local ok, err = pcall(function()\n        writefile(tmp, text)\n    end)\n\n    if not ok then\n        local directOk, directErr = pcall(function()\n            writefile(path, text)\n        end)\n        return directOk, directOk and nil or tostring(directErr or err)\n    end\n\n    local copied = pcall(function()\n        local content = readfile(tmp)\n        writefile(path, content)\n    end)\n\n    pcall(function()\n        if type(delfile) == "function" then\n            delfile(tmp)\n        end\n    end)\n\n    if not copied then\n        return false, "atomic copy failed"\n    end\n    return true\nend\n\nlocal MIN_VALID_EPOCH = 1600000000\n\nlocal function realEpoch()\n    local ok1, value1 = pcall(os.time)\n    if ok1 and type(value1) == "number" and value1 >= MIN_VALID_EPOCH then\n        return math.floor(value1)\n    end\n\n    local ok2, value2 = pcall(function()\n        return DateTime.now().UnixTimestamp\n    end)\n    if ok2 and type(value2) == "number" and value2 >= MIN_VALID_EPOCH then\n        return math.floor(value2)\n    end\n\n    local ok3, value3 = pcall(tick)\n    if ok3 and type(value3) == "number" and value3 >= MIN_VALID_EPOCH then\n        return math.floor(value3)\n    end\n\n    local ok4, value4 = pcall(function()\n        return workspace:GetServerTimeNow()\n    end)\n    if ok4 and type(value4) == "number" and value4 >= MIN_VALID_EPOCH then\n        return math.floor(value4)\n    end\n\n    return nil\nend\n\nlocal epochAnchor = realEpoch()\nlocal clockAnchor = os.clock()\n\nlocal function now()\n    local current = realEpoch()\n    if current then\n        epochAnchor = current\n        clockAnchor = os.clock()\n        return current\n    end\n\n    if epochAnchor then\n        return math.floor(\n            epochAnchor + math.max(0, os.clock() - clockAnchor)\n        )\n    end\n\n    return math.floor(MIN_VALID_EPOCH + os.clock())\nend\n\nlocal function toNumber(value)\n    local number = tonumber(value)\n    if type(number) ~= "number" then\n        return nil\n    end\n    if number ~= number or number == math.huge or number == -math.huge then\n        return nil\n    end\n    return number\nend\n\nlocal function truncateTwo(value)\n    value = toNumber(value)\n    if not value then\n        return nil\n    end\n    return math.floor(value * 100) / 100\nend\n\nlocal function firstValue(containers, names)\n    for _, item in ipairs(containers) do\n        local container = item\n        local path = ""\n\n        if type(item) == "table" and item.Value ~= nil then\n            container = item.Value\n            path = tostring(item.Path or "")\n        end\n\n        if type(container) == "table" then\n            for _, name in ipairs(names) do\n                local value = container[name]\n                if value ~= nil then\n                    local field = tostring(name)\n                    if path ~= "" then\n                        field = path .. "." .. field\n                    end\n                    return value, field\n                end\n            end\n        end\n    end\n    return nil, ""\nend\n\nlocal function entryContainers(entry)\n    if type(entry) ~= "table" then\n        return {}\n    end\n\n    -- Never create a sparse array here. ipairs() stops at the first nil.\n    local containers = {}\n\n    local function add(value, path)\n        if type(value) == "table" then\n            table.insert(containers, {\n                Value = value,\n                Path = tostring(path or ""),\n            })\n        end\n    end\n\n    add(entry, "")\n    add(entry.PetData, "PetData")\n    add(entry.Data, "Data")\n    add(entry.Properties, "Properties")\n    add(entry.Info, "Info")\n\n    return containers\nend\n\nlocal function scalarKeyList(entry, output, prefix)\n    if type(entry) ~= "table" then\n        return\n    end\n\n    prefix = tostring(prefix or "")\n\n    for key, value in pairs(entry) do\n        if type(key) == "string" then\n            local valueType = type(value)\n            if valueType ~= "function"\n                and valueType ~= "thread"\n                and valueType ~= "userdata" then\n                local observed = key\n                if prefix ~= "" then\n                    observed = prefix .. "." .. key\n                end\n                output[observed] = true\n            end\n        end\n    end\nend\n\nlocal function countTable(value)\n    local count = 0\n    if type(value) == "table" then\n        for _ in pairs(value) do\n            count += 1\n        end\n    end\n    return count\nend\n\nlocal function cleanString(value)\n    if value == nil then\n        return ""\n    end\n    return tostring(value)\nend\n\nlocal function collectTextValues(value, output, depth)\n    output = output or {}\n    depth = depth or 0\n\n    if depth > 3 then\n        return output\n    end\n\n    if type(value) == "string" then\n        local text = tostring(value)\n        text = string.gsub(text, "^%s+", "")\n        text = string.gsub(text, "%s+$", "")\n\n        if text ~= ""\n            and text ~= "Normal"\n            and text ~= "None"\n            and text ~= "Unknown" then\n            output[text] = true\n        end\n    elseif type(value) == "table" then\n        for key, item in pairs(value) do\n            if type(item) == "string" then\n                collectTextValues(item, output, depth + 1)\n            elseif item == true and tostring(key or "") ~= "" then\n                collectTextValues(tostring(key), output, depth + 1)\n            elseif type(item) == "table" then\n                collectTextValues(item, output, depth + 1)\n            end\n        end\n    end\n\n    return output\nend\n\nlocal function mutationInfo(entry)\n    local pd = type(entry.PetData) == "table"\n        and entry.PetData\n        or {}\n\n    local mutationMap = {}\n    local sources = {\n        {"MutationType", entry.MutationType},\n        {"Mutation", entry.Mutation},\n        {"Mutations", entry.Mutations},\n        {"MutationData", entry.MutationData},\n        {"AppliedMutations", entry.AppliedMutations},\n        {"ActiveMutations", entry.ActiveMutations},\n        {"PetData.MutationType", pd.MutationType},\n        {"PetData.Mutation", pd.Mutation},\n        {"PetData.Mutations", pd.Mutations},\n        {"PetData.MutationData", pd.MutationData},\n        {"PetData.AppliedMutations", pd.AppliedMutations},\n        {"PetData.ActiveMutations", pd.ActiveMutations},\n    }\n\n    local sourceField = ""\n    for _, item in ipairs(sources) do\n        if item[2] ~= nil and sourceField == "" then\n            sourceField = item[1]\n        end\n        collectTextValues(item[2], mutationMap, 0)\n    end\n\n    for _, key in ipairs({"Rainbow", "Gold", "Golden", "Shiny"}) do\n        if entry[key] == true or pd[key] == true then\n            mutationMap[key] = true\n            if sourceField == "" then\n                sourceField = entry[key] == true\n                    and key\n                    or ("PetData." .. key)\n            end\n        end\n    end\n\n    local names = {}\n    for name in pairs(mutationMap) do\n        table.insert(names, tostring(name))\n    end\n    table.sort(names)\n\n    if #names == 0 then\n        return "Normal", {}, (\n            sourceField ~= ""\n            and sourceField\n            or "default:Normal"\n        )\n    end\n\n    return table.concat(names, ", "), names, sourceField\nend\n\nlocal function parsePet(uuidKey, entry, observedKeys)\n    if type(entry) ~= "table" then\n        return nil, "entry_not_table"\n    end\n\n    scalarKeyList(entry, observedKeys, "")\n    scalarKeyList(entry.PetData, observedKeys, "PetData")\n    scalarKeyList(entry.Data, observedKeys, "Data")\n    scalarKeyList(entry.Properties, observedKeys, "Properties")\n    scalarKeyList(entry.Info, observedKeys, "Info")\n\n    local containers = entryContainers(entry)\n\n    local uuidValue = firstValue(\n        containers,\n        {"UUID", "Uuid", "uuid", "PetUUID", "PET_UUID", "Id", "ID"}\n    )\n    local nameValue, nameField = firstValue(\n        containers,\n        {"PetType", "PetName", "Name", "Type", "Species"}\n    )\n    local ageValue, ageField = firstValue(\n        containers,\n        {"Level", "Age", "PetAge"}\n    )\n    local baseWeightValue, baseWeightField = firstValue(\n        containers,\n        {\n            "BaseWeight",\n            "BaseWeightKg",\n            "BaseWeightKG",\n            "BaseWeight_kg",\n            "BaseWeightInKg",\n        }\n    )\n    local hatchedFromValue = firstValue(\n        containers,\n        {"HatchedFrom", "EggType", "SourceEgg"}\n    )\n    local favoriteValue = firstValue(\n        containers,\n        {"IsFavorite", "Favorite", "Favorited"}\n    )\n    local boostsValue = firstValue(\n        containers,\n        {"Boosts", "PetBoosts"}\n    )\n\n    local mutationText, mutationList, mutationField = mutationInfo(entry)\n\n    local uuid = cleanString(uuidValue)\n    if uuid == "" then\n        uuid = cleanString(uuidKey)\n    end\n\n    local name = cleanString(nameValue)\n    local age = toNumber(ageValue)\n    local rawBaseWeightAge0 = toNumber(baseWeightValue)\n\n    local baseWeightAge0 = nil\n    local baseWeightAge1 = nil\n\n    if rawBaseWeightAge0 then\n        baseWeightAge0 = truncateTwo(rawBaseWeightAge0)\n        baseWeightAge1 = truncateTwo(rawBaseWeightAge0 * 1.1)\n    end\n\n    local reasons = {}\n    if age and age >= Config.MinAge then\n        table.insert(reasons, "age")\n    end\n    if baseWeightAge1\n        and baseWeightAge1 >= Config.MinAge1BaseWeightKg then\n        table.insert(reasons, "weight")\n    end\n\n    return {\n        uuid = uuid,\n        name = name,\n        age = age,\n        base_weight_age0_kg = baseWeightAge0,\n        base_weight_age1_kg = baseWeightAge1,\n        mutation = mutationText,\n        mutations = mutationList,\n        hatched_from = cleanString(hatchedFromValue),\n        is_favorite = favoriteValue == true,\n        boost_count = countTable(boostsValue),\n        valuable = #reasons > 0,\n        valuable_reasons = reasons,\n\n        parsed_fields = {\n            name = nameField,\n            age = ageField,\n            base_weight = baseWeightField,\n            mutation = mutationField,\n        },\n    }, nil\nend\n\nlocal DataService = nil\nlocal function getDataService()\n    if DataService then\n        return DataService\n    end\n\n    local ok, result = pcall(function()\n        local modules = ReplicatedStorage:WaitForChild("Modules", 20)\n        local module = modules and modules:WaitForChild("DataService", 10)\n        return module and require(module)\n    end)\n\n    if ok and result then\n        DataService = result\n        return DataService\n    end\n\n    return nil\nend\n\nlocal function getPetInventory()\n    local service = getDataService()\n    if not service then\n        return nil, "DataService unavailable"\n    end\n\n    local ok, data = pcall(function()\n        return service:GetData()\n    end)\n    if not ok or type(data) ~= "table" then\n        return nil, "DataService:GetData failed"\n    end\n\n    local petsData = data.PetsData\n    local inventory = petsData and petsData.PetInventory\n    local petData = inventory and inventory.Data\n\n    if type(petData) ~= "table" then\n        return nil, "PetsData.PetInventory.Data missing"\n    end\n\n    return petData, nil\nend\n\nlocal function sortParsedPets(items)\n    table.sort(items, function(left, right)\n        local leftWeight = tonumber(left.base_weight_age1_kg) or -1\n        local rightWeight = tonumber(right.base_weight_age1_kg) or -1\n        if leftWeight ~= rightWeight then\n            return leftWeight > rightWeight\n        end\n\n        local leftAge = tonumber(left.age) or -1\n        local rightAge = tonumber(right.age) or -1\n        if leftAge ~= rightAge then\n            return leftAge > rightAge\n        end\n\n        local leftName = string.lower(tostring(left.name or ""))\n        local rightName = string.lower(tostring(right.name or ""))\n        if leftName ~= rightName then\n            return leftName < rightName\n        end\n\n        return tostring(left.uuid or "") < tostring(right.uuid or "")\n    end)\nend\n\nlocal WRITE_SEQ = 0\nlocal START_CLOCK = os.clock()\nlocal lastState = nil\n\nlocal function buildProbeState()\n    WRITE_SEQ += 1\n\n    local state = {\n        probe_version = Config.Version,\n        probe_revision = Config.Revision,\n        schema_version = 2,\n\n        username = LocalPlayer.Name,\n        display_name = LocalPlayer.DisplayName,\n        place_id = tostring(game.PlaceId or ""),\n        job_id = tostring(game.JobId or ""),\n        expected_place_id = tostring(Config.ExpectedPlaceId),\n        supported_place = tonumber(game.PlaceId) == Config.ExpectedPlaceId,\n\n        min_age = Config.MinAge,\n        min_age1_base_weight_kg = Config.MinAge1BaseWeightKg,\n        weight_mode = "BaseWeight age-0 multiplied by 1.1",\n        weight_precision = "truncate_2_decimals_no_rounding",\n\n        ts = now(),\n        write_seq = WRITE_SEQ,\n        script_uptime = math.floor(math.max(0, os.clock() - START_CLOCK)),\n        probe_alive = true,\n        probe_ready = false,\n        error = "",\n\n        inventory_entry_count = 0,\n        parsed_pet_count = 0,\n        valuable_pet_count = 0,\n        valuable_pets = {},\n        sample_pets = {},\n        observed_entry_keys = {},\n        missing_fields = {\n            name = 0,\n            age = 0,\n            base_weight = 0,\n            mutation = 0,\n            entry_not_table = 0,\n        },\n    }\n\n    if not usernameAllowed() then\n        state.error = "username not in AllowedUsernames"\n        return state\n    end\n\n    if Config.OnlyScanExpectedPlace\n        and tonumber(game.PlaceId) ~= Config.ExpectedPlaceId then\n        state.error = "outside expected Booster place"\n        return state\n    end\n\n    local petData, inventoryError = getPetInventory()\n    if not petData then\n        state.error = tostring(inventoryError or "pet inventory unavailable")\n        return state\n    end\n\n    local parsed = {}\n    local valuable = {}\n    local observedKeys = {}\n\n    for uuid, entry in pairs(petData) do\n        state.inventory_entry_count += 1\n\n        local pet, parseError = parsePet(uuid, entry, observedKeys)\n        if not pet then\n            if parseError == "entry_not_table" then\n                state.missing_fields.entry_not_table += 1\n            end\n        else\n            state.parsed_pet_count += 1\n\n            if pet.name == "" then\n                state.missing_fields.name += 1\n            end\n            if pet.age == nil then\n                state.missing_fields.age += 1\n            end\n            if pet.base_weight_age0_kg == nil then\n                state.missing_fields.base_weight += 1\n            end\n            if pet.mutation == "" then\n                state.missing_fields.mutation += 1\n            end\n\n            table.insert(parsed, pet)\n            if pet.valuable then\n                table.insert(valuable, pet)\n            end\n        end\n    end\n\n    sortParsedPets(parsed)\n    sortParsedPets(valuable)\n\n    for index = 1, math.min(#parsed, Config.MaxSamplePets) do\n        table.insert(state.sample_pets, parsed[index])\n    end\n\n    for index = 1, math.min(#valuable, Config.MaxValuablePets) do\n        table.insert(state.valuable_pets, valuable[index])\n    end\n\n    local keys = {}\n    for key in pairs(observedKeys) do\n        table.insert(keys, key)\n    end\n    table.sort(keys)\n\n    for index = 1, math.min(#keys, Config.MaxObservedKeys) do\n        table.insert(state.observed_entry_keys, keys[index])\n    end\n\n    state.valuable_pet_count = #valuable\n    state.valuable_pet_count_written = #state.valuable_pets\n    state.valuable_pet_list_truncated = #valuable > #state.valuable_pets\n    state.probe_ready = true\n    return state\nend\n\nlocal function writeProbeState(state)\n    safeMakeFolder(Config.WriteFolder)\n\n    local okEncode, encoded = pcall(function()\n        return HttpService:JSONEncode(state)\n    end)\n    if not okEncode then\n        return false, tostring(encoded)\n    end\n\n    local okWrite, writeError = safeWrite(Config.WriteFile, encoded)\n    if okWrite then\n        lastState = state\n    end\n    return okWrite, writeError\nend\n\nlocal function snapshot()\n    local state = buildProbeState()\n    local ok, err = writeProbeState(state)\n\n    if Config.Debug then\n        if ok then\n            print(\n                "[NOMO BOOSTER PROBE] wrote "\n                .. tostring(state.valuable_pet_count)\n                .. " valuable / "\n                .. tostring(state.parsed_pet_count)\n                .. " parsed"\n            )\n        else\n            warn("[NOMO BOOSTER PROBE] write failed:", tostring(err))\n        end\n    end\n\n    return state, ok, err\nend\n\ngetgenv().NOMO_BOOSTER_PROBE_STOP = function()\n    Config.Enabled = false\n    Config.Stop = true\n    print("[NOMO BOOSTER PROBE] stop requested")\nend\n\ngetgenv().NOMO_BOOSTER_PROBE_SNAPSHOT = function()\n    local state, ok, err = snapshot()\n    print(\n        "[NOMO BOOSTER PROBE] snapshot:",\n        ok and "written" or tostring(err)\n    )\n    return state\nend\n\ngetgenv().NOMO_BOOSTER_PROBE_DUMP = function()\n    local state = lastState or buildProbeState()\n    print(HttpService:JSONEncode(state))\n    return state\nend\n\nprint("========================================")\nprint("[NOMO BOOSTER PROBE] " .. Config.Version)\nprint("[NOMO BOOSTER PROBE] account = " .. LocalPlayer.Name)\nprint("[NOMO BOOSTER PROBE] writing -> " .. Config.WriteFile)\nprint(\n    "[NOMO BOOSTER PROBE] valuable = age >= "\n    .. tostring(Config.MinAge)\n    .. " OR age1 base >= "\n    .. string.format("%.2f", Config.MinAge1BaseWeightKg)\n    .. "kg"\n)\nprint("[NOMO BOOSTER PROBE] production counter/state untouched")\nprint("========================================")\n\npcall(snapshot)\n\ntask.spawn(function()\n    while Config.Enabled and not Config.Stop do\n        task.wait(Config.ScanEvery)\n\n        local ok, err = pcall(snapshot)\n        if not ok then\n            warn(\n                "[NOMO BOOSTER PROBE] loop error:",\n                tostring(err)\n            )\n        end\n    end\n\n    Config.Enabled = false\n    Config.Stop = true\n    print("[NOMO BOOSTER PROBE] stopped")\nend)\n'


def booster_probe_autoexec_source():
    """Build remote -> per-UID last-good -> embedded verified Booster scanner."""
    remote_url = json.dumps(NOMO_BOOSTER_PROBE_URL)
    embedded = _lua_long_string(BOOSTER_PROBE_FALLBACK_TEMPLATE)

    return f'''-- NOMO Booster scanner updater/loader
-- NOMO Booster loader revision 2
-- Priority: GitHub latest -> per-UID last-good -> legacy cache -> embedded verified v0.1.1

local Players = game:GetService(\"Players\")
local LocalPlayer = Players.LocalPlayer or Players.PlayerAdded:Wait()
local PROBE_URL = {remote_url}
local CACHE_FOLDER = \"nomo_rejoiner\"
local CACHE_FILE = CACHE_FOLDER .. \"/nomo_booster_probe_cache_\" .. tostring(LocalPlayer.UserId or \"unknown\") .. \".lua\"
local LEGACY_CACHE_FILE = CACHE_FOLDER .. \"/nomo_booster_probe_cache.lua\"
local EMBEDDED_FALLBACK = {embedded}

local function validProbeSource(text)
    return type(text) == \"string\"
        and #text > 5000
        and string.find(text, \"NOMO BOOSTER PROBE\", 1, true) ~= nil
        and string.find(text, \"NOMO_BOOSTER_PROBE\", 1, true) ~= nil
        and string.find(text, \"v0.1.1-petdata-container-fix\", 1, true) ~= nil
end

local function ensureCacheFolder()
    if type(makefolder) ~= \"function\" then return end
    pcall(function()
        if type(isfolder) == \"function\" then
            if not isfolder(CACHE_FOLDER) then makefolder(CACHE_FOLDER) end
        else
            makefolder(CACHE_FOLDER)
        end
    end)
end

local function saveCache(text)
    if type(writefile) ~= \"function\" or not validProbeSource(text) then return false end
    ensureCacheFolder()
    local ok = pcall(function() writefile(CACHE_FILE, text) end)
    return ok
end

local function readCachePath(path)
    if type(readfile) ~= \"function\" then return nil end
    local ok, text = pcall(function()
        if type(isfile) == \"function\" and not isfile(path) then return nil end
        return readfile(path)
    end)
    if ok and validProbeSource(text) then return text end
    return nil
end

local function runSource(text, name)
    if not validProbeSource(text) then
        return false, \"source validation failed\"
    end
    local chunk, compileError = loadstring(text)
    if not chunk then
        return false, \"compile failed: \" .. tostring(compileError)
    end
    print(\"[NOMO BOOSTER LOADER] source = \" .. tostring(name))
    local runOk, runError = pcall(chunk)
    if not runOk then
        return false, \"runtime failed: \" .. tostring(runError)
    end
    return true, \"ok\"
end

local remoteOk, remoteText = pcall(function()
    return game:HttpGet(PROBE_URL, true)
end)
if remoteOk and validProbeSource(remoteText) then
    local ok, err = runSource(remoteText, \"github\")
    if ok then
        saveCache(remoteText)
        return
    end
    warn(\"[NOMO BOOSTER LOADER] remote rejected; keeping last-good:\", tostring(err))
end

local cached = readCachePath(CACHE_FILE)
if cached then
    local ok, err = runSource(cached, \"cache\")
    if ok then return end
    warn(\"[NOMO BOOSTER LOADER] per-UID cache failed:\", tostring(err))
end

local legacy = readCachePath(LEGACY_CACHE_FILE)
if legacy then
    local ok, err = runSource(legacy, \"legacy-cache\")
    if ok then
        saveCache(legacy)
        return
    end
    warn(\"[NOMO BOOSTER LOADER] legacy cache failed:\", tostring(err))
end

local ok, err = runSource(EMBEDDED_FALLBACK, \"embedded-v0.1.1\")
if not ok then
    warn(\"[NOMO BOOSTER LOADER] embedded fallback failed:\", tostring(err))
end
'''


AUTOEXEC_DEFAULT_CUSTOM_FILE = "nomo_autoexec.lua"
AUTOEXEC_PET_COUNTER_FILE = "nomo_pet_counter.lua"
AUTOEXEC_BOOSTER_PROBE_FILE = "nomo_booster_probe.lua"
AUTOEXEC_MARKET_LOADER_FILE = "nomo_market_loader.lua"
_AUTOEXEC_ALLOWED_SUFFIXES = {".lua", ".luau", ".txt"}

# Obsolete names created by older NOMO/GAG setup versions. This list must stay
# narrow: never include generic names like autoexec.lua, loader.lua, init.lua,
# or any third-party hub filename. Cleanup is opt-in and off by default.
LEGACY_SETUP_AUTOEXEC_NAMES = {
    "gag_pet_counter_loader.lua",
    "gap_pet_counter_loader.lua",
    "gag_pet_counter.lua",
    "gap_pet_counter.lua",
    "pet_counter_loader.lua",
    "hatching.lua",
}
LEGACY_SETUP_DISABLED_SUFFIX = ".disabled_v4582.bak"


def autoexec_dir_from_state_path(state_path):
    """Resolve the one real executor AutoExec directory from a clone state path.

    Arceus X stores startup scripts beside Workspace in ``Arceus X/Autoexec``.
    Delta stores them in ``Delta/Autoexecute``.  The old
    ``Arceus X/Workspace/autoexec`` path never existed and is intentionally not
    returned.
    """
    raw = str(state_path or "").strip().replace("\\", "/")
    if not raw:
        return None

    lower = raw.lower()
    arceus_marker = "/arceus x/workspace/"
    if arceus_marker in lower:
        idx = lower.index(arceus_marker)
        return Path(raw[:idx]) / "Arceus X" / "Autoexec"

    delta_marker = "/delta/workspace/"
    if delta_marker in lower:
        idx = lower.index(delta_marker)
        return Path(raw[:idx]) / "Delta" / "Autoexecute"

    # Fallback for unusual state filenames while still requiring a known
    # executor folder.  Never guess a Workspace/autoexec directory.
    p = Path(raw)
    parts = list(p.parts)
    for i, part in enumerate(parts):
        pl = str(part).lower()
        if pl == "arceus x":
            return Path(*parts[: i + 1]) / "Autoexec"
        if pl == "delta":
            return Path(*parts[: i + 1]) / "Autoexecute"
    return None


def autoexec_base_from_state_path(state_path):
    """Backward-compatible helper returning the executor root folder."""
    folder = autoexec_dir_from_state_path(state_path)
    return folder.parent if folder is not None else None


def autoexec_dirs_for_tab(tab, mode="both"):
    # ``mode`` is kept only so older call sites/configs remain compatible.
    # Every mode resolves to exactly one correct executor directory.
    explicit = str(tab.get("autoexec_path") or "").strip()
    folder = Path(explicit) if explicit else autoexec_dir_from_state_path(
        tab.get("stat_file") or tab.get("state_file") or ""
    )
    if folder is None:
        return []
    label = "Delta/Autoexecute" if folder.name.lower() == "autoexecute" else "Arceus X/Autoexec"
    return [(label, folder)]


def autoexec_paths_for_tab(tab, mode="both", filename=AUTOEXEC_DEFAULT_CUSTOM_FILE):
    return [folder / filename for _, folder in autoexec_dirs_for_tab(tab, mode)]


def autoexec_tabs(cfg):
    tabs = []
    seen = set()
    for tab in cfg.get("tabs", []):
        pkg = tab.get("package")
        if pkg and pkg not in seen:
            tabs.append(tab)
            seen.add(pkg)
    try:
        hcfg = load_hatcher_config()
        for prof in hatcher_profiles(hcfg, enabled_only=False):
            pkg = prof.get("package")
            if pkg and pkg not in seen:
                tabs.append(hatcher_profile_to_tab(prof))
                seen.add(pkg)
    except Exception:
        pass
    return tabs


def _autoexec_selected_tabs(cfg, title):
    tabs = autoexec_tabs(cfg)
    if not tabs:
        print(col("No packages found in config.", RED))
        pause()
        return []
    selected_pkgs = choose_packages_common(
        cfg,
        title,
        multi=True,
        include_discovered=False,
        configured_only=True,
    )
    if not selected_pkgs:
        return []
    selected_map = {t.get("package"): t for t in tabs}
    selected = [selected_map[p] for p in selected_pkgs if p in selected_map]
    if not selected:
        print(col("Selected packages have no configured AutoExec paths.", RED))
        pause()
    return selected


def _print_autoexec_full_paths(selected_tabs, cfg=None, heading="Resolved AutoExec path(s)"):
    print("")
    print(col(heading + ":", BOLD))
    shown = 0
    for tab in selected_tabs or []:
        pkg = str(tab.get("package") or "?")
        dirs = autoexec_dirs_for_tab(tab, "1")
        if not dirs:
            print(col(f"  {pkg} -> UNRESOLVED (check state_file)", RED))
            continue
        for _label, folder in dirs:
            print(f"  {col(pkg, CYAN)} -> {folder}")
            shown += 1
    return shown


def _choose_autoexec_location(cfg, allow_both=True, selected_tabs=None):
    """Show the exact paths and select the single valid AutoExec location.

    ``allow_both`` is retained for compatibility; V4.03 deliberately has no
    second Workspace/autoexec destination.
    """
    shown = _print_autoexec_full_paths(selected_tabs or [], cfg)
    if selected_tabs and shown == 0:
        print(col("No valid AutoExec path could be resolved.", RED))
        pause()
        return None
    return "1"


def _safe_autoexec_filename(raw, default=AUTOEXEC_DEFAULT_CUSTOM_FILE):
    name = clean_terminal_input(raw) or default
    name = Path(name).name
    name = re.sub(r"[^A-Za-z0-9_.-]+", "_", name).strip("._")
    if not name:
        name = default
    suffix = Path(name).suffix.lower()
    if suffix not in _AUTOEXEC_ALLOWED_SUFFIXES:
        name += ".lua"
    return name[:120]


def _format_bytes(size):
    try:
        size = int(size)
    except Exception:
        return "?"
    if size < 1024:
        return f"{size}B"
    if size < 1024 * 1024:
        return f"{size / 1024:.1f}K"
    return f"{size / (1024 * 1024):.1f}M"


def _collect_autoexec_files(selected_tabs, path_mode="both"):
    records = []
    seen = set()
    empty_dirs = []
    for tab in selected_tabs:
        pkg = str(tab.get("package") or "")
        dirs = autoexec_dirs_for_tab(tab, path_mode)
        if not dirs:
            empty_dirs.append((pkg, "cannot derive AutoExec folder"))
            continue
        for label, folder in dirs:
            folder_key = (pkg, str(folder))
            try:
                files = [p for p in folder.iterdir() if p.is_file()] if folder.exists() else []
            except Exception as exc:
                empty_dirs.append((pkg, f"{label}: {exc}"))
                continue
            files = sorted(files, key=lambda p: p.name.lower())
            if not files:
                empty_dirs.append((pkg, f"{label}: empty/missing"))
            for path in files:
                key = (pkg, str(path))
                if key in seen:
                    continue
                seen.add(key)
                try:
                    size = path.stat().st_size
                except Exception:
                    size = -1
                records.append({
                    "package": pkg,
                    "location": label,
                    "path": path,
                    "size": size,
                })
    return records, empty_dirs


def _parse_index_selection(raw, count, allow_all=True):
    raw = clean_terminal_input(raw)
    low = raw.lower()
    if allow_all and low in {"a", "all"}:
        return list(range(count))
    chosen = []
    for token in re.split(r"[\s,]+", raw):
        token = token.strip()
        if not token:
            continue
        if re.fullmatch(r"\d+-\d+", token):
            a, b = [int(x) for x in token.split("-", 1)]
            step = 1 if b >= a else -1
            for num in range(a, b + step, step):
                idx = num - 1
                if 0 <= idx < count and idx not in chosen:
                    chosen.append(idx)
            continue
        if token.isdigit():
            idx = int(token) - 1
            if 0 <= idx < count and idx not in chosen:
                chosen.append(idx)
    return chosen


def _print_autoexec_file_table(records, cfg):
    rows = []
    for i, rec in enumerate(records, 1):
        rows.append([
            (str(i), CYAN),
            (short_pkg(rec["package"]), WHITE),
            (rec["location"], DIM),
            (rec["path"].name, WHITE),
            (_format_bytes(rec["size"]), DIM, True),
        ])
    draw_table(["No", "Package", "Location", "File", "Size"], rows,
               [3, 10, 18, 28, 7], cfg)


def _choose_autoexec_records(records, action="Choose file(s)", multi=True):
    print("")
    print(col(action, BOLD))
    print(col("Use numbers/ranges (1,3-5), A=all, 0=back.", DIM))
    while True:
        raw = clean_terminal_input(input("Choose: "))
        if raw.lower() in {"", "0", "q", "quit", "b", "back"}:
            return []
        idxs = _parse_index_selection(raw, len(records), allow_all=True)
        if idxs:
            if not multi:
                idxs = idxs[:1]
            return [records[i] for i in idxs]
        print(col("Invalid file selection.", RED))


def _read_autoexec_text(path, max_chars=40000):
    try:
        data = path.read_bytes()
    except Exception as exc:
        return None, f"read failed: {exc}", False
    truncated = len(data) > max_chars
    data = data[:max_chars]
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        text = data.decode("utf-8", errors="replace")
    return text, "", truncated


def autoexec_view_files(cfg):
    selected = _autoexec_selected_tabs(cfg, "AUTOEXEC: VIEW CONTENTS")
    if not selected:
        return
    path_mode = _choose_autoexec_location(cfg, allow_both=True, selected_tabs=selected)
    if path_mode is None:
        return
    records, empty_dirs = _collect_autoexec_files(selected, path_mode)
    clear()
    banner("AUTOEXEC FILES", cfg)
    if not records:
        print(col("No AutoExec files found in the selected folder(s).", YELLOW))
        for pkg, note in empty_dirs:
            print(col(f"{short_pkg(pkg)}: {note}", DIM))
        pause()
        return
    _print_autoexec_file_table(records, cfg)
    chosen = _choose_autoexec_records(records, "View which file(s)?", multi=True)
    if not chosen:
        return
    for rec in chosen:
        clear()
        banner(f"{short_pkg(rec['package'])}: {rec['path'].name}", cfg)
        print(col(str(rec["path"]), DIM))
        print(col("─" * term_width(cfg), DIM))
        content, err, truncated = _read_autoexec_text(rec["path"])
        if err:
            print(col(err, RED))
        else:
            lines = content.splitlines()
            if not lines:
                print(col("<empty file>", YELLOW))
            else:
                for no, line_text in enumerate(lines, 1):
                    print(f"{col(str(no).rjust(4), DIM)}  {line_text}")
            if truncated:
                print(col("\n<preview truncated at 40 KB>", YELLOW))
        pause()


def _write_autoexec_script(selected, path_mode, filename, script, cfg, replace_prompt=True):
    destinations = []
    for tab in selected:
        paths = autoexec_paths_for_tab(tab, path_mode, filename=filename)
        if not paths:
            print(col(f"{tab.get('package')}: cannot derive AutoExec path", RED))
            continue
        for path in paths:
            destinations.append((tab.get("package"), path))
    if not destinations:
        pause()
        return 0

    existing = [(pkg, path) for pkg, path in destinations if path.exists()]
    print("")
    print(col("Destinations:", BOLD))
    for pkg, path in destinations:
        state = "REPLACE" if path.exists() else "CREATE"
        state_color = YELLOW if path.exists() else GREEN
        print(f"  {col(short_pkg(pkg), CYAN)}  {col(state, state_color)}  {path}")
    if existing and replace_prompt:
        ans = clean_terminal_input(input("\nReplace existing selected file(s)? [Y/n]: ")).lower()
        if ans in {"n", "no"}:
            print(col("Cancelled; nothing changed.", YELLOW))
            pause()
            return 0

    wrote = 0
    unchanged = 0
    for pkg, path in destinations:
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            old = None
            if path.exists():
                try:
                    old = path.read_text(encoding="utf-8")
                except Exception:
                    old = None
            if old == script:
                print(col(f"Unchanged: {path}", DIM))
                unchanged += 1
                continue
            _write_nomo_autoexec_text(path, script)
            print(col(f"Saved: {path}", GREEN))
            wrote += 1
        except Exception as exc:
            print(col(f"Failed: {path} -> {exc}", RED))
    print(col(f"\nDone. Wrote {wrote}; unchanged {unchanged}.", GREEN if wrote or unchanged else YELLOW))
    pause()
    return wrote


