def main():
    cfg = load_config()
    nomo_auto_repair_launchers_once(cfg)
    try:
        moved, cleanup_errors = cleanup_nomo_autoexec_backup_artifacts(cfg)
        if moved:
            log_activity(f"AutoExec NOMO backup cleanup: moved {moved} file(s) outside AutoExec", "", GREEN)
        if cleanup_errors:
            log_activity(f"AutoExec NOMO backup cleanup warnings: {len(cleanup_errors)}", "", YELLOW)
    except Exception as exc:
        log_activity(f"AutoExec NOMO backup cleanup skipped: {cut(exc, 90)}", "", YELLOW)
    try:
        upgraded = upgrade_known_nomo_market_loader_once(cfg)
        if upgraded:
            log_activity(f"AutoExec NOMO loader upgraded: {upgraded} file(s)", "", GREEN)
        aux_upgraded = upgrade_known_nomo_aux_loaders_once(cfg)
        if aux_upgraded:
            log_activity(f"AutoExec NOMO counter/booster loader upgraded: {aux_upgraded} file(s)", "", GREEN)
        # The upgrade itself must never leave a staging/backup artifact behind.
        moved_after, cleanup_errors_after = cleanup_nomo_autoexec_backup_artifacts(cfg)
        if moved_after:
            log_activity(f"AutoExec post-upgrade cleanup: moved {moved_after} file(s)", "", GREEN)
        if cleanup_errors_after:
            log_activity(f"AutoExec post-upgrade cleanup warnings: {len(cleanup_errors_after)}", "", YELLOW)
    except Exception as exc:
        log_activity(f"AutoExec NOMO loader upgrade skipped: {cut(exc, 90)}", "", YELLOW)
    try:
        exotic_key_manager_tick(cfg)
    except Exception as exc:
        log_activity(f"Exotic key manager startup failed: {cut(exc, 90)}", "", YELLOW)

    while True:
        reset_terminal()
        drain_stdin()

        normalize_active_mode_flags(cfg)

        main_menu(cfg)
        choice = read_menu_choice("[?] Option: ", {str(x[0]) for x in MAIN_MENU_ITEMS})
        if choice is None:
            print(col("Invalid option. Use one of the numbers shown in the menu.", RED))
            time.sleep(1)
            continue

        if choice == "1":
            cfg = load_config()
            mode = active_rejoin_mode(cfg)

            # Same pre-start stage for every mode, just like other startup
            # preparation such as Market workspace/config export.
            run_startup_cache_cleanup(
                cfg,
                selected_packages=None,
                reason=(
                    "Option 1 pre-start "
                    + mode
                ),
                setup=False,
                show_screen=True,
            )

            try:
                start_active_rejoin_mode(cfg)
            finally:
                reset_terminal()
                drain_stdin()
            cfg = load_config()
            normalize_active_mode_flags(cfg)

        elif choice == "2":
            mode_menu(cfg)
            cfg = load_config()
            normalize_active_mode_flags(cfg)

        elif choice == "3":
            select_package_menu(cfg)
            cfg = load_config()
            normalize_active_mode_flags(cfg)

        elif choice == "4":
            get_all_usernames_via_api(cfg)
            cfg = load_config()
            normalize_active_mode_flags(cfg)

        elif choice == "5":
            set_global_private_server_menu(cfg)
            cfg = load_config()
            normalize_active_mode_flags(cfg)

        elif choice == "6":
            try:
                force_restart_active_tabs_once(cfg)
            finally:
                reset_terminal()
                drain_stdin()
            cfg = load_config()
            normalize_active_mode_flags(cfg)

        elif choice == "7":
            cookie_menu(cfg)
            cfg = load_config()
            normalize_active_mode_flags(cfg)

        elif choice == "8":
            import_cookie_menu(cfg)
            cfg = load_config()
            if normalize_active_mode_flags(cfg):
                save_config(cfg)

        elif choice == "9":
            advanced_tools_menu(cfg)
            cfg = load_config()
            normalize_active_mode_flags(cfg)

        elif choice == "10":
            solver_menu(cfg)
            cfg = load_config()
            normalize_active_mode_flags(cfg)

        elif choice == "11":
            config_settings(cfg)
            cfg = load_config()
            normalize_active_mode_flags(cfg)

        elif choice == "12":
            autoexec_menu(cfg)
